window.IB_BANKS["system-design"] = {"questions":[{"id":"sysd-001","seq":1,"title":"让你设计一个 RPC 框架，怎么设计？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":false,"category":"后端系统设计面试题"},{"id":"sysd-002","seq":2,"title":"如何设计一个秒杀功能？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-003","seq":3,"title":"让你设计一个消息队列，怎么设计？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-004","seq":4,"title":"让你设计一个线程池，怎么设计？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-005","seq":5,"title":"让你设计一个 HashMap ，怎么设计？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-006","seq":6,"title":"让你设计一个短链系统，怎么设计？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-007","seq":7,"title":"让你实现一个订单超时取消功能，怎么设计？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-008","seq":8,"title":"让你实现一个分布式单例对象，如何实现？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-009","seq":9,"title":"商家想要知道自己店铺卖的最好的 top 50 商品，如何实现这个功能？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-010","seq":10,"title":"朋友圈点赞功能如何实现，简单说说？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-011","seq":11,"title":"分布式锁一般都怎样实现？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-012","seq":12,"title":"如果让你统计每个接口每分钟调用次数怎么统计？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-013","seq":13,"title":"让你设计一个文件上传系统，怎么设计？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-014","seq":14,"title":"让你设计一个分布式 ID 发号器，怎么设计？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-015","seq":15,"title":"什么是限流？限流算法有哪些？怎么实现的？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-016","seq":16,"title":"如何设计一个点赞系统？","content":"","difficulty":"中等","tags":["系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-017","seq":17,"title":"即时通讯项目中怎么实现历史消息的下拉分页加载？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题"],"vip":false,"category":"后端系统设计面试题"},{"id":"sysd-018","seq":18,"title":"HashMap 是不是线程安全的？如果让你来实现一个线程安全的 HashMap 你要怎么设计？如果不用加锁你要怎么设计？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-019","seq":19,"title":"让你设计一个购物车功能，怎么设计？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-020","seq":20,"title":"怎么设计电商系统的订单数据同步方案（同步到数仓）？要求数据准确、性能高","content":"","difficulty":"中等","tags":["后端","场景题","系统设计题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-021","seq":21,"title":"设计一个实时数据同步系统，将 MySQL 数据实时同步到数据仓库？","content":"","difficulty":"中等","tags":["后端","场景题","系统设计题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-022","seq":22,"title":"如何设计一个高可用的数据同步系统？需要考虑哪些容错机制？","content":"","difficulty":"中等","tags":["后端","场景题","系统设计题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-023","seq":23,"title":"让你设计一个 API 网关，需要考虑哪些核心功能？如何实现动态路由和限流？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题","API网关","微服务","限流"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-024","seq":24,"title":"API 网关如何实现接口版本管理？如果要同时支持 v1、v2、v3 多个版本的接口，你会怎么设计？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","API网关"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-025","seq":25,"title":"网关层如何防止接口重放攻击？如果攻击者抓取了请求包进行重放，你如何识别和拦截？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","API网关","安全"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-026","seq":26,"title":"微服务架构中，如何设计一个配置中心？配置变更后如何实时通知各个服务？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题","配置中心"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-027","seq":27,"title":"如果配置中心挂了，各个微服务应该如何保证可用性？你会设计什么降级策略？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","微服务","配置中心"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-028","seq":28,"title":"电商系统中，用户下单后如何保证订单、库存、支付三个服务的数据一致性？请设计一个分布式事务方案","content":"","difficulty":"困难","tags":["后端","系统设计","场景题","电商"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-029","seq":29,"title":"如果让你实现一个分布式事务的补偿机制，应该注意哪些问题？补偿失败了怎么办？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","分布式事务"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-030","seq":30,"title":"分布式缓存中，如何实现一致性 Hash 算法？相比普通 Hash，它解决了什么问题？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","一致性Hash","分布式缓存","负载均衡"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-031","seq":31,"title":"如何设计一个灰度发布系统？如何控制流量逐步切换到新版本？","content":"","difficulty":"困难","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-032","seq":32,"title":"如何实现一个单点登录（SSO）系统？如果有多个子系统，用户只需登录一次即可访问所有系统","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","单点登录"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-033","seq":33,"title":"SSO 系统中，如果认证中心挂了怎么办？如何保证已登录用户不受影响？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","单点登录"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-034","seq":34,"title":"如何设计一个接口签名验证机制？防止参数被篡改和重放攻击？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","安全"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-035","seq":35,"title":"接口中的敏感数据（如身份证号、手机号）应该如何加密传输和存储？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","安全"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-036","seq":36,"title":"加密后的数据怎么支持模糊搜索？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-037","seq":37,"title":"如何防止接口被恶意刷量？除了限流，还有哪些防护手段？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","安全"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-038","seq":38,"title":"如何实现一个滑动验证码功能？如何防止被机器识别破解？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","安全","人机识别","验证码"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-039","seq":39,"title":"短信验证码如何防止被恶意轰炸？如果有人不断请求发送验证码，你会如何限制？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","安全"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-040","seq":40,"title":"什么是死信队列？在什么场景下会用到？如何设计死信队列的处理机制？","content":"","difficulty":"中等","tags":["后端","系统设计","场景题","消息队列"],"vip":true,"category":"后端系统设计面试题"},{"id":"sysd-041","seq":41,"title":"微信扫码登录是如何实现的？请描述一下技术方案","content":"","difficulty":"中等","tags":["后端","场景题","系统设计"],"vip":true,"category":"后端系统设计面试题"}],"answers":{"sysd-001":"**一句话结论**：RPC = 动态代理 + 序列化 + 网络传输 + 注册中心 + 负载均衡与容错，把远程调用伪装成本地方法调用。\n\n### 关键点\n\n1. **代理层**：消费者面向接口编程，启动时用 JDK、CGLIB 或 ByteBuddy 生成动态代理，方法调用被拦截后封装成请求。\n2. **协议与序列化**：自定义二进制协议含魔数、版本、消息类型、长度、请求 ID；序列化选 Protobuf/Hessian，避免 Java 原生序列化。\n3. **网络传输**：服务端基于 Netty NIO 长连接，编解码 Handler 加心跳检测和断线重连，支撑高并发连接。\n4. **注册与发现**：服务启动把地址注册到 ZK/Nacos/etcd，消费者订阅并本地缓存，配合推送感知上下线。\n5. **治理能力**：负载均衡（轮询、随机、一致性哈希、最少连接）、超时、重试、熔断降级、限流、链路追踪和泛化调用。\n\n### 图示\n\n```mermaid\nsequenceDiagram\n    participant C as 消费者\n    participant P as 动态代理\n    participant N as Netty 客户端\n    participant R as 注册中心\n    participant S as 服务端\n    C->>P: 调用本地接口方法\n    P->>R: 拉取可用服务列表\n    R-->>P: 返回地址并本地缓存\n    P->>P: 序列化并封装请求\n    P->>N: 通过长连接发送\n    N->>S: 传输二进制协议\n    S->>S: 解码后反射调用实现类\n    S-->>N: 返回响应\n    N-->>P: 解码响应\n    P-->>C: 反序列化返回结果\n```\n\n### 常见追问\n\n- **为什么用 Netty 不用 BIO？** NIO 多路复用，少量线程管理大量连接；BIO 一连接一线程，高并发撑不住。\n- **序列化怎么选？** Protobuf 体积小、跨语言、性能高；Hessian 对 Java 友好；Java 原生序列化体积大且有安全问题。\n- **超时和重试怎么做？** 设置连接和读超时，重试要幂等且限制次数，连续失败触发熔断，避免雪崩。\n- **服务上下线怎么感知？** 注册中心 Watcher 推送加客户端本地缓存，配合心跳剔除故障节点。\n\n### 踩坑点\n\n- 只答 Netty 加序列化，漏掉动态代理、注册中心、负载均衡这些框架骨架。\n- 重试不做幂等，超时重发导致重复扣款、重复下单。\n- 长连接不做心跳，TCP 假死时请求一直挂到超时。","sysd-002":"**一句话结论**：秒杀靠层层削峰：静态化挡住大部分流量，网关限流，Redis Lua 原子预扣，MQ 异步下单，DB 幂等兜底防超卖。\n\n### 关键点\n\n1. **前端静态化**：活动页走 CDN，倒计时结束才放开按钮；点击后置灰并携带一次性防重令牌，避免重复提交。\n2. **入口限流**：网关按 IP、用户、接口限流，叠加风控（黑名单、频控）和限购（每人限 N 件），把无效流量挡在服务之外。\n3. **库存预扣**：库存提前加载到 Redis，用 Lua 把「判断库存 + 扣减 + 记录用户购买」做成原子操作；热点商品独立集群或分片，避免大 key。\n4. **异步下单**：扣减成功后只发一条 MQ 消息就返回「排队中」，由消费者串行创建订单，把 DB 写入削峰填谷。\n5. **DB 兜底**：下单用 `update stock = stock - 1 where stock > 0` 乐观锁或唯一索引防超卖；订单做幂等键；失败回滚库存，前端轮询结果。\n\n### 图示\n\n```mermaid\nflowchart TD\n    U[\"用户点击秒杀\"] --> S[\"静态页 + CDN<br/>按钮置灰 + 防重令牌\"]\n    S --> G[\"网关限流 + 风控 + 限购\"]\n    G --> R{\"Redis Lua<br/>原子预扣库存\"}\n    R -->|\"库存不足\"| F[\"直接返回售罄\"]\n    R -->|\"扣减成功\"| M[\"发送 MQ 消息<br/>返回排队中\"]\n    M --> C[\"消费者异步创建订单\"]\n    C --> D{\"DB 乐观锁 / 唯一索引\"}\n    D -->|\"成功\"| OK[\"订单落库<br/>前端轮询结果\"]\n    D -->|\"失败\"| RB[\"回滚 Redis 库存<br/>记录失败流水\"]\n```\n\n### 常见追问\n\n- **Redis 扣了库存但下单失败怎么办？** 回滚库存并记录流水，MQ 重试进死信后由定时任务对账补偿。\n- **怎么防超卖？** Redis Lua 原子扣减是第一道，DB 的 `stock > 0` 条件更新和唯一索引是最后一道，两层都要有。\n- **为什么用 MQ 不直接写库？** 瞬时流量远超 DB 写入能力，MQ 削峰后按能力消费，用户端轮询或推送结果。\n- **热点 key 怎么处理？** 库存按分片拆成多个 key 汇总扣减，或独立 Redis 集群，配合本地缓存抗读。\n\n### 踩坑点\n\n- 只做 Redis 预扣不做 DB 兜底，Redis 宕机或消息丢失就会超卖。\n- 「先 get 库存再 set 扣减」不是原子操作，高并发下必然超卖，必须用 Lua 或 `DECR`。\n- 忘记幂等，MQ 重投会生成重复订单。","sysd-003":"**一句话结论**：队列本质是顺序写日志加分区分片加位点消费，先把不丢、不重、堆积可控做出来，再谈功能。\n\n### 约束与目标\n\n- 日增十亿级消息，单主题峰值几万 TPS，保留七天到 TB 级。\n- 至少一次投递，允许秒级延迟，不允许静默丢失。\n- 目标：堆积时可水平扩容，故障切换一分钟内完成。\n- 不做：不做精确一次投递，业务侧用幂等消化重复。\n\n### 拆解思路\n\n1. **存储**：分区一个追加写文件加稀疏索引，顺序写避免随机读，消费按位点顺序推进。\n2. **副本**：主副本收写、从副本同步，同步完成的副本集合决定能否应答，切主选集合里最新的副本。\n3. **生产**：批量发送降往返，失败重试带本地待发队列，关键业务加本地消息表保证最终一致。\n4. **消费**：拉模式按批拉取，处理完再提交位点，失败不提交从而重投，业务必须幂等。\n\n### 图示\n\n```mermaid\nflowchart LR\n    P[\"生产端<br/>批量发送 失败重试\"] --> B[\"Broker 主副本\"]\n    B --> L[\"分区日志<br/>追加写 稀疏索引\"]\n    B --> S1[\"从副本一\"]\n    B --> S2[\"从副本二\"]\n    L --> CG[\"消费组<br/>拉模式 批量\"]\n    CG --> BIZ[\"业务处理<br/>幂等\"]\n    CG --> OFF[\"位点提交\"]\n    OFF --> L\n```\n\n### 关键选型与取舍\n\n- **拉模式而非推模式**：消费者自己控速，堆积时不会被推垮；代价是空闲有轮询开销，低延迟要配长轮询，极高实时性场景反而适合推。\n- **日志型而非传统队列型**：保留期内可重放、多消费组各自维护位点；代价是存储成本高、单分区顺序受限，一次性任务用队列型更省。\n- **至少一次而非精确一次**：实现简单、吞吐高；代价是必须幂等，跨系统事务靠本地消息表加对账兜底。\n\n### 风险与兜底\n\n- **消息丢失**：副本未同步就应答 → 多数派同步完成才应答，关键主题刷盘。\n- **重复消费**：位点回退或重投 → 业务唯一键幂等，重复丢弃并计数。\n- **堆积雪崩**：消费变慢 → 超阈值先限流生产端，再扩分区与消费者。\n- **重平衡抖动**：实例频繁上下线 → 会话超时调大，滚动发布逐个摘除实例。\n\n### 面试加分点\n\n- 分区数上限受文件句柄与恢复时间约束，按目标吞吐除以单分区能力估算，不是越多越好。\n- 位点回溯重放是日志型队列的隐藏价值，故障时能重算下游。","sysd-004":"**一句话结论**：线程池不是调参而是容量问题，先按任务类型定队列与线程数，再按业务隔离，最后才是拒绝策略。\n\n### 约束与目标\n\n- 单机十六核，任务以 IO 与 CPU 混合为主，峰值并发数千。\n- 不允许无界队列，不允许静默丢弃，慢任务不能拖垮核心业务。\n- 目标：核心接口排队时间可控，过载时快速失败而不是雪崩。\n- 不做：不做跨机调度，只解决进程内并发治理。\n\n### 拆解思路\n\n1. **分类估算**：CPU 密集线程数约等于核数，IO 密集按等待与计算时间之比放大，再留两成余量。\n2. **队列定界**：长度按可接受排队时长乘处理速率估算，宁可短队列加拒绝，不要长队列掩盖过载。\n3. **隔离与拒绝**：按业务域拆池避免慢依赖占满公共池，核心链路用调用方执行或快速失败返回兜底。\n4. **监控**：暴露活跃线程、队列长度、拒绝次数、任务耗时，参数走配置中心热更新。\n\n### 图示\n\n```mermaid\nflowchart LR\n    T[\"任务提交\"] --> P[\"业务线程池A\"]\n    T --> Q[\"业务线程池B\"]\n    P --> Q1[\"有界队列\"]\n    Q1 --> W[\"工作线程\"]\n    W --> H[\"业务处理\"]\n    Q1 -->|\"队列满\"| REJ[\"拒绝策略<br/>降级或快速失败\"]\n    W --> M[\"指标上报<br/>活跃 队列 拒绝 耗时\"]\n```\n\n### 关键选型与取舍\n\n- **有界队列而非无界**：过载能被立刻看见，避免堆到内存溢出；代价是高峰期真会拒绝请求，要准备兜底文案与重试入口。\n- **按业务隔离而非共享大池**：一个慢依赖不会拖垮全站；代价是线程与内存占用上升，依赖都很快时共享池更划算。\n- **调用方执行而非静默丢弃**：背压传回上游，天然限流；代价是上游被拖慢，响应敏感的核心接口应改成快速失败。\n\n### 风险与兜底\n\n- **队列堆积**：处理慢于提交 → 长度告警，连续超阈值自动降级非核心任务。\n- **任务卡死**：下游无响应 → 任务级超时加中断，定期打印长耗时栈。\n- **线程泄漏**：阻塞调用无超时 → 统一超时加线程数上限与拒绝兜底。\n- **优雅停机**：发布时任务被硬杀 → 先拒新任务，再排空在飞任务，超时落库补偿。\n\n### 面试加分点\n\n- 到达速率接近服务速率时排队时间指数上升，容量要按峰值七八成留余量。\n- 参数和压测绑定，说出核心数来自压测比背公式更有说服力。","sysd-005":"**一句话结论**：数组加链表加红黑树是冲突与内存的权衡，关键在扰动函数、负载因子和扩容时的高低链拆分。\n\n### 约束与目标\n\n- 单实例千万级键值，读多写少，单次查询微秒级。\n- 内存敏感，不能为降冲突无限加大数组。\n- 目标：平均查找接近常数，最坏不退化成长链表。\n- 不做：不做持久化与跨进程共享，并发交给并发容器。\n\n### 拆解思路\n\n1. **定位**：先取哈希再扰动，把高位掺进低位避免大量碰撞；长度取二的幂，位运算代替取模。\n2. **冲突**：冲突少用链表，链表超阈值且容量足够就树化，节点变少再转回链表。\n3. **扩容**：负载因子到阈值翻倍，按高低位拆成两条链，避免每个节点重算下标。\n4. **并发与内存**：本身非线程安全，并发写会丢数据甚至成环，迭代器快速失败；键值对象开销远大于桶数组。\n\n### 图示\n\n```mermaid\nflowchart LR\n    K[\"key\"] --> H[\"hash 扰动<br/>高位掺低位\"]\n    H --> I[\"桶下标<br/>按位与取模\"]\n    I --> B[\"桶数组\"]\n    B --> N1[\"链表节点\"]\n    N1 --> N2[\"链表节点\"]\n    N2 -->|\"长度超阈值\"| T[\"红黑树\"]\n    B -->|\"元素超阈值\"| RS[\"扩容两倍<br/>高低位拆分\"]\n```\n\n### 关键选型与取舍\n\n- **二的幂容量而非质数**：位运算更快、扩容拆分简单；代价是分布更依赖扰动函数，哈希函数弱时冲突比质数取模明显。\n- **链表转红黑树而非一直链表**：最坏查找从线性降到对数；代价是树节点内存翻倍、维护复杂，所以阈值设得较高。\n- **非线程安全而非默认加锁**：单线程无锁开销；代价是并发误用会静默出错，高并发场景直接用并发容器。\n\n### 风险与兜底\n\n- **碰撞攻击**：构造同桶键退化成链表 → 树化兜底，入口限制参数长度与键类型。\n- **扩容风暴**：大量写入反复扩容 → 初始化按预估容量给足，批量导入用预设容量。\n- **并发写丢数据**：多线程写入 → 代码评审加静态检查，热点场景换并发容器。\n- **大对象驻留**：键值过大 → 限制缓存规模，配淘汰策略与内存监控。\n\n### 面试加分点\n\n- 树化阈值与退化阈值不对称，是为了避免在边界反复转换。\n- 扩容拆高低位两条链是工程巧劲，讲清这点比背源码行号更显理解。","sysd-006":"**一句话结论**：发号器生成全局唯一 ID，Base62 编码成短码，MySQL 存映射、Redis 挡读，访问时 302 跳转。\n\n### 关键点\n\n1. **发号 + 编码**：Snowflake 或号段发号器生成唯一 ID，转 62 进制（0-9、a-z、A-Z），6 位约 568 亿种组合。\n2. **存储**：MySQL 表用 `short_code` 唯一索引加 `long_url`；Redis 缓存短码到长链接的映射，空值也缓存防穿透。\n3. **跳转**：返回 302 临时重定向，方便统计点击和随时改目标；301 会被浏览器长期缓存，统计失真。\n4. **自定义短码**：用户指定时先查 Redis/DB，插入靠唯一索引兜底，冲突则提示或加随机后缀。\n5. **防遍历与治理**：发号 ID 加随机盐或加密，避免自增被爬；布隆过滤器加限流挡恶意遍历；记录 PV/UV，支持过期与回收。\n\n### 图示\n\n```mermaid\nflowchart TD\n    A[\"长链接提交\"] --> B[\"发号器<br/>Snowflake / 号段\"]\n    B --> C[\"Base62 编码成 6 位短码\"]\n    C --> D[\"写 MySQL<br/>short_code 唯一索引\"]\n    D --> E[\"写 Redis 缓存\"]\n    U[\"用户访问短链\"] --> R{\"Redis 是否命中？\"}\n    R -->|\"命中\"| J[\"302 重定向到长链接\"]\n    R -->|\"未命中\"| DB[\"查 MySQL 并回填缓存\"]\n    DB --> J\n    J --> S[\"异步记录点击统计\"]\n```\n\n### 常见追问\n\n- **为什么用 302？** 302 不缓存，每次请求都到服务端，才能统计和改目标；301 是永久重定向，浏览器会缓存。\n- **短码冲突怎么办？** 自增发号天然不冲突；自定义短码靠唯一索引，插入失败就换码或提示。\n- **怎么防止被遍历？** ID 加盐或加密让短码不可预测，再叠加布隆过滤器、IP 限流和风控。\n- **读多写少怎么优化？** Redis 缓存加本地缓存多级兜底，热点短链甚至可静态化到 CDN。\n\n### 踩坑点\n\n- 用自增 ID 直接 Base62，短码连续可枚举，业务量也暴露。\n- 只查 MySQL 不加缓存，跳转 QPS 一高就打爆库。\n- 用 301 做跳转，统计全丢且目标改不了。","sysd-007":"**一句话结论**：延迟消息为主、扫表兜底，靠状态机与版本号解决支付与取消的并发竞态，保证只取消一次。\n\n### 约束与目标\n\n- 日订单百万级，超时三十分钟，允许秒级误差。\n- 不能取消已支付订单，不能重复取消，退款不能漏。\n- 目标：超时取消成功率接近满值，异常订单能被对账捞回。\n- 不做：不做毫秒级倒计时，前端展示与后台任务解耦。\n\n### 拆解思路\n\n1. **状态机**：待支付、已支付、已取消、已退款之间只允许有限迁移，写操作都带当前状态做条件更新。\n2. **延迟消息**：下单发一条延迟消息，到期按订单号查状态，仍是待支付才取消并回补库存。\n3. **扫表兜底**：定时任务按创建时间分片扫过期订单补发取消，防消息丢失。\n4. **竞态与补偿**：取消与支付同时到达时用版本号让输方失败；回补库存走幂等接口，退款异步记流水，日终对账。\n\n### 图示\n\n```mermaid\nsequenceDiagram\n    participant O as 订单服务\n    participant MQ as 延迟消息\n    participant C as 取消消费者\n    participant DB as 订单库\n    participant S as 库存服务\n    O->>DB: 创建待支付订单\n    O->>MQ: 发送延迟消息\n    MQ->>C: 到期投递\n    C->>DB: 条件更新待支付转取消\n    DB-->>C: 成功或已被支付\n    C->>S: 回补库存幂等\n    O->>DB: 支付回调改状态\n```\n\n### 关键选型与取舍\n\n- **延迟消息而非纯扫表**：到期即时触发、数据库压力小；代价是精度受延迟级别限制且可能丢失，扫表必须保留。\n- **扫表做兜底而非主路径**：兜底是订单系统的生命线；代价是全表扫描压力大，要分片、限批、错峰。\n- **条件更新而非先查后改**：避免取消覆盖支付；代价是失败分支多，代码比一把大锁复杂。\n- **取消即回补而非等退款**：库存能快速释放；代价是有超卖风险，回补必须幂等并对账校验。\n\n### 风险与兜底\n\n- **消息丢失**：队列异常 → 扫表任务独立可用，监控超时待支付订单的存量水位。\n- **重复取消**：消息与扫表同时命中 → 状态条件更新加取消流水唯一键，第二次跳过。\n- **扫表打库**：大促全表扫描 → 分片加限速、低峰执行，必要时只扫最近几小时。\n- **退款遗漏**：取消成功退款失败 → 本地消息表加重试，日终对账拉差异告警。\n\n### 面试加分点\n\n- 延迟消息只负责准时、扫表负责不漏，这个分工比堆技术更显工程判断。\n- 分库分表后扫表要按分片键路由，这是很多设计里漏掉的一步。","sysd-008":"**一句话结论**：分布式单例的本质是同一时刻只有一个持有者，注册中心抢主加租约续期，再用令牌序号防双主同时写。\n\n### 约束与目标\n\n- 集群十台左右，允许秒级主切换，不允许两节点同时写同一份数据。\n- 目标：主节点宕机后一分钟内自动选出新主，切换过程可观测。\n- 不做：不做跨机房强一致选主，不做多写合并。\n- 约束：依赖现有注册中心能力，不自研共识协议。\n\n### 拆解思路\n\n1. **选主**：启动时在注册中心争抢临时节点，抢到的成为主，其余转备并监听变化。\n2. **租约**：主定期续约上报心跳，续约失败即失去资格并主动停服，避免假活。\n3. **防分裂脑**：每次选主生成递增令牌，写请求与下游调用都带令牌，接收方只认更大序号。\n4. **切换**：主挂后监听者触发重选，新主先对齐状态再打开流量开关，长任务写前分段校验租约。\n\n### 图示\n\n```mermaid\nflowchart LR\n    N1[\"节点一\"] --> Z[\"注册中心<br/>临时节点抢主\"]\n    N2[\"节点二\"] --> Z\n    N3[\"节点三\"] --> Z\n    Z -->|\"抢到\"| M[\"主节点\"]\n    Z -->|\"未抢到\"| B[\"备节点<br/>监听变化\"]\n    M --> L[\"租约续期<br/>心跳上报\"]\n    L -->|\"失败\"| S[\"停止对外服务\"]\n    M --> W[\"写共享资源<br/>携带令牌\"]\n    B -->|\"主消失\"| E[\"发起重新选主\"]\n```\n\n### 关键选型与取舍\n\n- **临时节点而非缓存锁**：主挂后会话节点自动消失，语义天然匹配；代价是强依赖注册中心与会话超时配置，轻量场景用带过期的缓存锁更简单。\n- **强一致选主而非多写可用**：宁可短暂不可写也不能双写；代价是切换窗口内不可用，优先可用且能合并写的场景该选多主。\n- **令牌序号而非单纯加锁**：写入侧自带顺序能挡住过期主；代价是所有写路径都要透传令牌，改造成本不小。\n\n### 风险与兜底\n\n- **网络分区双主**：主与注册中心失联仍存活 → 令牌校验加租约到期停服，下游只认更大序号。\n- **主节点假活**：进程卡住不续约 → 续约线程独立于业务线程，卡住即判失联。\n- **切换抖动**：节点频繁抢主 → 选主退避与最短任期，连续切换告警。\n- **状态不一致**：新主未对齐就接流量 → 切换内置状态校验，未通过不开开关。\n\n### 面试加分点\n\n- 令牌序号是防双写关键，只讲选主不讲写入校验，一旦分区就写坏数据。\n- 选主要做演练，定期手工杀主验证切换时长与对齐是否真的生效。","sysd-009":"**一句话结论**：不要每次实时排序，写入侧增量计数进有序集合，定时生成榜单快照，读接口只读快照。\n\n### 约束与目标\n\n- 单店商品数千，订单日百万，榜单分钟级延迟可接受。\n- 查询 QPS 高，不能扫全表也不能实时聚合大表。\n- 目标：榜单接口 P99 十毫秒内，结果与订单口径一致。\n- 不做：不做毫秒级实时榜，不做跨店全局榜。\n\n### 拆解思路\n\n1. **明确口径**：先定销量件数还是成交额、是否含退款、窗口是七天还是自然周，口径不定后面全是返工。\n2. **增量计数**：支付成功后按商品在有序集合累加分数，按周期分键避免单键无限增长。\n3. **生成快照**：定时任务取前五十写快照表并带生成时间，读接口只查快照并按店铺加周期缓存。\n4. **冷启动**：新店或数据修复时用历史订单跑回填脚本，幂等可重跑，避免榜单空缺。\n\n### 图示\n\n```mermaid\nflowchart LR\n    O[\"支付成功事件\"] --> C[\"计数服务<br/>按周期分键\"]\n    C --> Z[\"有序集合<br/>商品分数\"]\n    T[\"定时任务<br/>分钟级\"] --> Z\n    Z --> S[\"取前五十名\"]\n    S --> TBL[\"榜单快照表\"]\n    Q[\"商家后台查询\"] --> CACHE[\"榜单缓存\"]\n    CACHE --> TBL\n    B[\"回填脚本\"] --> Z\n```\n\n### 关键选型与取舍\n\n- **有序集合而非数据库聚合**：累加是内存操作，取前五十是对数复杂度；代价是数据在内存、要考虑持久化，量大并发低时直接 SQL 聚合更简单。\n- **快照读而非实时排名**：读路径极快且稳定；代价是分钟级延迟，活动期间要留手动刷新入口。\n- **固定周期键而非全局大键**：避免大键与无限增长；代价是跨周期合并要额外逻辑，窗口切换时榜单一度为空要预热。\n\n### 风险与兜底\n\n- **重复计数**：消息重投导致虚高 → 订单号做幂等标记，同一订单只加一次。\n- **大键膨胀**：商品多、周期多 → 按天分键并设过期，历史数据归档到数据库。\n- **榜单空白**：缓存与快照双失效 → 保留上一版快照兜底，返回带时间戳的旧数据。\n- **口径不一致**：退款未扣、跨天归属错 → 日终对账比对快照与明细，差异告警并重算。\n\n### 面试加分点\n\n- 先说口径再谈实现，销量榜与销售额榜的结构完全不同，这里最容易拉开差距。\n- 只展示前五十但集合要留更大候选池，避免尾部商品因计数延迟掉出后无法回升。","sysd-010":"**一句话结论**：点赞关系与计数分开存，关系放 Redis 集合支持去重与查询，计数单独维护，展示层只读聚合结果。\n\n### 约束与目标\n\n- 单条动态点赞可达百万级，读远多于写，允许最终一致。\n- 目标：响应十毫秒内，重复点赞不重复计数，能查最近点赞的人。\n- 不做：不做每条点赞的实时推送，不做全量明细常驻内存。\n- 约束：用现有缓存与数据库实现，不引入新中间件。\n\n### 拆解思路\n\n1. **数据模型**：按动态存点赞用户的有序集合并带时间戳，天然去重且能按时间分页取最近的人。\n2. **计数**：点赞数单独一个计数器，展示时只读计数，不遍历集合。\n3. **写入**：先写集合，新增成功才计数加一，已存在则跳过，避免重复计。\n4. **展示与归档**：详情读计数与是否已赞，列表批量取计数；明细异步落库用于统计与恢复，冷数据定期归档。\n\n### 图示\n\n```mermaid\nflowchart LR\n    U[\"用户点赞\"] --> API[\"点赞接口\"]\n    API --> SET[\"Redis 有序集合<br/>按动态分键\"]\n    SET -->|\"新增成功\"| CNT[\"计数器加一\"]\n    SET -->|\"已存在\"| DUP[\"忽略并返回\"]\n    API --> MQ[\"异步消息\"]\n    MQ --> DB[\"明细归档库\"]\n    V[\"浏览者\"] --> READ[\"展示接口<br/>计数与是否已赞\"]\n    READ --> CNT\n    READ --> SET\n```\n\n### 关键选型与取舍\n\n- **Redis 集合而非数据库唯一索引**：写入快、天然去重、能按时间取人；代价是要防大键，持久化靠异步落库，数据少且要强持久时直接落库更稳。\n- **计数与关系分离而非遍历求长度**：读计数是常数时间；代价是两边可能短暂不一致，需要定时校准。\n- **最终一致而非强一致**：点赞是弱业务，容忍短暂偏差；代价是极端时计数差几个，靠定时任务修正。\n\n### 风险与兜底\n\n- **大键**：热门动态集合过大 → 按动态分键并限制集合长度，超出部分只进计数。\n- **重复计数**：网络重试 → 集合加入结果作幂等判据，计数器只在新增时加。\n- **缓存故障**：集合不可用 → 降级只展示计数并隐藏名单，写入转异步补偿。\n- **刷赞**：异常账号高频点赞 → 按用户限流，异常行为进风控队列。\n\n### 面试加分点\n\n- 点赞数允许不精确是这类业务的共识，敢说用定时校准比追求强一致更成熟。\n- 分页用时间戳游标而非页码，百万级集合上页码分页会越翻越慢。","sysd-011":"**一句话结论**：主流三种：Redis 的 SET NX PX 加 Lua 释放、ZooKeeper 临时顺序节点加 Watcher、数据库唯一索引；Redis 快但一致性弱，ZK 一致性强但慢。\n\n### 关键点\n\n1. **Redis**：`SET lockKey uuid NX PX 30000` 原子加锁并设过期；释放用 Lua 比对 uuid 再 DEL，防止误删；Redisson 提供可重入和 watchdog 续期。\n2. **ZooKeeper**：在锁节点下建临时顺序节点，序号最小者持锁，其余监听前一个节点；会话断开临时节点自动删除，天然避免死锁。\n3. **数据库**：唯一索引 insert 抢锁，或 `update ... where version = ?`；释放靠删除记录，宕机靠过期时间或定时清理，性能最差。\n4. **对比**：一致性 ZK、etcd 强于 DB，DB 强于 Redis；性能 Redis 最好、ZK 次之、DB 最差；Redis 主从异步复制，切换时可能短暂双持锁。\n5. **选型**：高并发短临界区选 Redis，强一致选 ZK/etcd，低并发或不想引入中间件就用 DB。\n\n### 图示\n\n```mermaid\nflowchart TD\n    A[\"分布式锁实现\"] --> B[\"Redis<br/>SET NX PX + Lua 释放\"]\n    A --> C[\"ZooKeeper<br/>临时顺序节点 + Watcher\"]\n    A --> D[\"数据库<br/>唯一索引 / 版本号\"]\n    B --> B1[\"性能高<br/>主从切换有脑裂风险\"]\n    C --> C1[\"CP 强一致<br/>会话断开自动释放\"]\n    D --> D1[\"实现简单<br/>性能差、易死锁\"]\n```\n\n### 常见追问\n\n- **锁过期但业务没跑完？** 后台 watchdog 定时续期；临界区尽量短，或改用能感知会话的 ZK。\n- **Redis 主从切换会丢锁吗？** 异步复制下新主可能没有锁记录，旧主仍在执行，形成双持锁；强一致场景用 ZK/etcd，或 RedLock 降低概率。\n- **可重入锁怎么做？** Redis 用 Hash 存 uuid 和计数，Lua 加减，减到 0 才删 key。\n- **ZK 和 etcd 怎么选？** 都是 CP，ZK 用 ZAB 加 Watcher，etcd 用 Raft 加 Lease，云原生环境更常用 etcd。\n\n### 踩坑点\n\n- `setnx` 成功后再 `expire` 不是原子操作，中间宕机就是永久死锁。\n- 释放锁直接 DEL 不校验 value，会删掉别人后来加的锁。\n- 以为 RedLock 绝对安全，网络分区和时钟漂移下仍有争议。","sysd-012":"**一句话结论**：请求侧只做内存打点，按分钟桶本地聚合后定时上报，查询侧读时序存储，不要把每次调用写进数据库。\n\n### 约束与目标\n\n- 单机每秒上万请求，接口数百个，统计延迟一分钟可接受。\n- 目标：统计开销低于请求耗时的百分之一，数据可按时段查询与告警。\n- 不做：不做逐请求明细留存，不做秒级实时大盘。\n- 约束：多实例部署，要能按实例与接口维度汇总。\n\n### 拆解思路\n\n1. **埋点位置**：放在网关或统一拦截器，一处覆盖全部接口，避免业务代码到处埋。\n2. **本地聚合**：内存里按接口加分钟维护计数，原子累加避免锁竞争，切换时把上一桶送进待上报队列。\n3. **上报**：定时批量上报，失败时本地保留若干个桶，重启后补报避免丢数据。\n4. **存储与告警**：时序库存接口加分钟的计数，按分钟设阈值与同比环比规则告警。\n\n### 图示\n\n```mermaid\nflowchart LR\n    R[\"请求\"] --> I[\"拦截器埋点\"]\n    I --> B[\"本地分钟桶<br/>原子累加\"]\n    B -->|\"分钟切换\"| Q[\"待上报队列\"]\n    Q --> U[\"批量上报\"]\n    U --> S[\"采集服务\"]\n    S --> TS[\"时序存储<br/>接口加分钟\"]\n    TS --> D[\"查询大盘\"]\n    TS --> AL[\"阈值告警\"]\n```\n\n### 关键选型与取舍\n\n- **本地聚合而非请求级写入**：开销可忽略，数据库压力降几个量级；代价是有上报延迟与重启丢桶风险，需要补报机制。\n- **计数器而非明细日志**：存储成本极低；代价是无法回溯单个请求，排障要依赖链路追踪。\n- **时序库而非关系库**：按时间范围聚合快；代价是多一套组件与运维成本，接口规模很小时宽表也够。\n- **固定分钟粒度而非滑动窗口**：实现简单、聚合稳定；代价是边界处有毛刺，要靠更长窗口平滑。\n\n### 风险与兜底\n\n- **重复或漏算**：上报失败重试 → 上报带实例与分钟唯一键，服务端覆盖写入，天然幂等。\n- **重启丢桶**：进程被杀前未上报 → 桶落本地文件，启动后补报最近若干分钟。\n- **高基数膨胀**：维度爆炸 → 只保留接口加分钟主维度，实例维度按需采样。\n- **统计失真**：漏掉异步入口 → 埋点覆盖异步线程与消息消费，定期校验总量。\n\n### 面试加分点\n\n- 先说统计口径是入口请求数还是成功响应数，口径不同结论可能完全相反。\n- 采样要讲误差：高 QPS 接口按比例采样再乘系数，低 QPS 接口必须全量，否则告警阈值没意义。","sysd-013":"**一句话结论**：客户端直传对象存储，服务端只签发凭证与记录元数据，大文件分片加断点续传，服务端不碰字节流。\n\n### 约束与目标\n\n- 单文件最大 GB 级，日上传几十万次，要防盗链防恶意文件。\n- 目标：成功率高于九成九，失败能续传，带宽成本可控。\n- 不做：不做服务端转码，不自建多副本存储。\n- 约束：鉴权与配额要能按用户维度控制。\n\n### 拆解思路\n\n1. **申请凭证**：客户端先拿预签名地址与短期令牌，服务端做登录校验、配额与类型白名单。\n2. **直传分片**：小文件一次直传，大文件按固定大小切片并行，每片带序号，服务端只记录上传会话。\n3. **合并校验**：分片完成触发合并，校验大小与摘要，通过后写元数据并置为可用。\n4. **访问与清理**：下载走短时效签名或 CDN 鉴权；未完成会话定时清理，上传后做病毒扫描，不合规隔离。\n\n### 图示\n\n```mermaid\nflowchart LR\n    C[\"客户端\"] --> API[\"上传服务<br/>鉴权 配额 白名单\"]\n    API -->|\"预签名凭证\"| C\n    C -->|\"分片直传\"| OSS[\"对象存储\"]\n    C -->|\"完成通知\"| API\n    API --> META[\"元数据表\"]\n    OSS --> SCAN[\"安全扫描\"]\n    SCAN -->|\"通过\"| META\n    API --> CDN[\"下载签名<br/>或 CDN 鉴权\"]\n```\n\n### 关键选型与取舍\n\n- **客户端直传而非服务端中转**：省带宽与临时磁盘，成本降一个量级；代价是客户端要处理分片重试，弱网兼容成本高，内网小文件场景中转更简单。\n- **对象存储而非自建**：弹性与可靠性现成；代价是按量计费与厂商绑定，强合规要评估私有化。\n- **分片并行而非单流上传**：大文件速度与续传能力更好；代价是合并与一致性逻辑复杂，小文件反而增加往返开销。\n- **预签名短时效而非长期密钥**：泄露风险最小；代价是过期前要重取，长任务需刷新。\n\n### 风险与兜底\n\n- **分片丢失或乱序**：弱网中断 → 服务端记录已完成分片清单，续传只补缺失片，超时会话定期回收。\n- **恶意文件**：伪装类型或超大文件 → 类型白名单加大小上限，异步扫描，不合规隔离并通知。\n- **盗链与越权**：签名地址被转发 → 短时效加来源校验，敏感文件鉴权后再签发。\n- **元数据不一致**：合并成功但入库失败 → 完成回调幂等，定时对账扫孤儿对象。\n\n### 面试加分点\n\n- 秒传靠内容摘要命中已有对象，能把重复素材的上传成本压到接近零。\n- 热数据走标准层、冷备转低频，成本能降一半以上。","sysd-014":"**一句话结论**：按唯一性、有序性、性能取舍：号段模式和 Snowflake 最常用，UUID 只适合不要求有序、不暴露规模的场景。\n\n### 关键点\n\n1. **UUID**：本地生成、无网络开销、水平扩展容易；但 128 位太长且无序，做 MySQL 主键会导致 B+ 树页分裂、索引膨胀。\n2. **数据库自增/号段**：单表自增简单但有单点瓶颈；Leaf-segment 一次取一段号缓存在内存，双 buffer 预取，DB 只负责分配号段。\n3. **Redis INCR**：内存操作性能高，但依赖持久化，集群要按步长分片（如 3 节点分别 +3），重启可能丢号。\n4. **Snowflake**：64 位 = 1 位符号 + 41 位毫秒时间戳 + 10 位机器 ID + 12 位序列号；本地生成、趋势递增，每毫秒每机器 4096 个。\n5. **Leaf-snowflake**：workerId 由 ZooKeeper 顺序节点分配，启动校验时钟，回拨时等待或报警，解决 Snowflake 依赖系统时钟的问题。\n\n### 图示\n\n```mermaid\nflowchart TD\n    A[\"分布式 ID 方案\"] --> B[\"UUID<br/>无序、128 位\"]\n    A --> C[\"DB 自增 / 号段<br/>Leaf-segment 双 buffer\"]\n    A --> D[\"Redis INCR<br/>按步长分片\"]\n    A --> E[\"Snowflake\"]\n    E --> F[\"1 位符号 + 41 位时间戳<br/>+ 10 位机器 + 12 位序列\"]\n    F --> G[\"趋势递增、依赖时钟\"]\n    G --> H[\"Leaf-snowflake<br/>ZK 分配 workerId + 回拨检测\"]\n```\n\n### 常见追问\n\n- **时钟回拨怎么处理？** 记录上次时间戳，小幅回拨等待追平，大幅回拨拒绝发号并报警，或切换到备用 workerId。\n- **为什么 UUID 不适合做主键？** 无序导致随机写入，B+ 树频繁页分裂；长度也拖大索引和缓存。\n- **号段模式重启会重号吗？** 不会，DB 持久化当前 max_id，重启后重新取新号段，只是浪费未用完的号。\n- **容器化后机器 ID 怎么分配？** 用 ZK、etcd 或配置中心自动分配并持久化，别写死 IP。\n\n### 踩坑点\n\n- 机器 ID 重复，多实例部署直接 ID 冲突，必须集中分配。\n- 说 Snowflake 严格递增，它是趋势递增，同毫秒内靠序列号，跨机器不保证全局顺序。\n- Redis INCR 单 key 不设步长，集群扩容后号段会乱。","sysd-015":"**一句话结论**：限流是保护系统的手段：固定窗口、滑动窗口、漏桶、令牌桶；单机用 Guava，分布式用 Redis 加 Lua 或 Sentinel。\n\n### 关键点\n\n1. **固定窗口**：按时间分桶计数，实现最简单；临界问题明显，两个窗口交界可能瞬间放行 2 倍流量。\n2. **滑动窗口**：把窗口拆成小格或记录请求时间戳，按滑动区间统计，平滑很多；Redis ZSET 存时间戳即可实现。\n3. **漏桶**：请求先进桶，以恒定速率流出，桶满即拒绝；输出绝对平滑，保护下游，但不允许突发。\n4. **令牌桶**：按恒定速率往桶里放令牌，桶有容量上限，请求拿到令牌才放行；允许一定突发，Guava RateLimiter 就是它。\n5. **落地**：单机用 Guava 或 Sentinel 本地限流；分布式用 Redis 加 Lua 保证原子，或用 Sentinel 集群流控；维度按 IP、用户、接口、集群，拒绝策略可选快速失败、排队或预热。\n\n### 图示\n\n```mermaid\nflowchart TD\n    A[\"限流算法\"] --> B[\"固定窗口<br/>简单，临界双倍流量\"]\n    A --> C[\"滑动窗口<br/>平滑，需存时间戳\"]\n    A --> D[\"漏桶<br/>恒定流出，不允许突发\"]\n    A --> E[\"令牌桶<br/>恒速发令牌，允许突发\"]\n    B --> F[\"单机：Guava / Sentinel\"]\n    C --> G[\"分布式：Redis + Lua\"]\n    D --> G\n    E --> F\n    G --> H[\"维度：IP / 用户 / 接口 / 集群\"]\n```\n\n### 常见追问\n\n- **固定窗口的临界问题？** 窗口 1 末尾和窗口 2 开头各放行满额，瞬时是阈值 2 倍；滑动窗口或令牌桶能缓解。\n- **令牌桶和漏桶区别？** 令牌桶按请求取令牌，桶容量允许突发；漏桶按固定速率流出，输出恒定、不允许突发。\n- **分布式限流怎么做？** Redis 加 Lua 把计数和判断做成原子，key 按接口加维度；注意热点和单点，可用 Sentinel token server。\n- **阈值怎么定？** 压测得出单机容量，按集群规模分配，预留 buffer，并支持动态调整和预热。\n\n### 踩坑点\n\n- 只做单机限流，集群多实例后总流量翻 N 倍，等于没限。\n- 只按 IP 限流，NAT 后大量用户共用一个出口，容易误伤。\n- 拒绝策略只有抛异常，没有排队、降级和友好提示。","sysd-016":"**一句话结论**：Redis 扛读写：Set 或 Hash 记谁点过、计数器记总数，MQ 异步批量落库，唯一键保幂等，热 key 分片。\n\n### 关键点\n\n1. **状态存储**：用 Redis Set 存目标下的 userId 集合，或 Hash 存用户维度状态；计数器用 String 的 INCR/DECR。\n2. **原子与幂等**：点赞 `SADD` 返回 1 才 `INCR`，取消 `SREM` 返回 1 才 `DECR`，用 Lua 把两步合成原子操作，天然防重复。\n3. **异步落库**：变更发 MQ，消费者批量写 MySQL；点赞表用 `(user_id, target_id)` 唯一索引兜底，计数表单独维护。\n4. **防刷限流**：按用户加目标做频控，叠加风控和黑名单，避免脚本刷赞。\n5. **热 key 与榜单**：大 V 的点赞集合按用户 ID 分片成多个 key 再汇总；榜单用 ZSET，score 存点赞数或时间。\n\n### 图示\n\n```mermaid\nflowchart TD\n    U[\"用户点赞\"] --> L{\"限流 / 风控\"}\n    L -->|\"拒绝\"| R[\"返回稍后再试\"]\n    L -->|\"通过\"| S[\"Lua：SADD 返回 1 才 INCR\"]\n    S -->|\"已点过\"| D[\"幂等返回成功\"]\n    S -->|\"新增\"| M[\"发 MQ 异步落库\"]\n    M --> DB[\"批量写 MySQL<br/>唯一索引防重\"]\n    S --> C[\"更新计数 / 榜单 ZSET\"]\n```\n\n### 常见追问\n\n- **Redis 和 DB 不一致怎么办？** 展示以 Redis 为准，MQ 保证最终一致，定时对账加缓存重建兜底。\n- **大 key 怎么处理？** 按用户 ID 哈希分片成多个 Set，读时聚合；或只存最近活跃用户，冷数据落库。\n- **点赞列表怎么分页？** Set 无序不方便分页，改用 ZSET，score 存时间，按时间倒序 range。\n- **取消点赞并发重复怎么办？** 同样用 Lua 保证 SREM 和 DECR 原子，重复取消不再减。\n\n### 踩坑点\n\n- 先 `SISMEMBER` 再 `SADD` 再 `INCR`，三步非原子，并发下重复计数。\n- 每次点赞同步写 DB，热点内容直接把库打挂。\n- 单 Set 存千万级用户 ID，大 key 阻塞、扩容困难。","sysd-017":"**一句话结论**：历史消息用会话内单调序号做游标，按会话分片、反向存储，最近消息进缓存，把深分页变成一次范围扫描。\n\n### 约束与目标\n\n- 单会话历史最多 10 万条，单页 20 到 50 条，下拉翻页 P99 小于 100ms。\n- 目标：翻页不重不丢，连续下拉一百页耗时稳定，冷热切换对用户透明。\n- 不做什么：不做跨会话搜索与任意跳页，历史导出走离线任务。\n\n### 拆解思路\n\n1. **游标分页**：用会话内自增序号，查询带小于上页最小序号，按序号倒序取一页，避开偏移量。\n2. **存储**：按会话标识哈希分片，行键用会话标识加反向序号，顺序扫描即得最近若干条。\n3. **缓存**：每个会话最近两百条放有序集合，首屏与浅翻页命中，超出范围回源存储。\n4. **写入与客户端**：写入时分配会话内序号并路由同片；客户端滚动触底才请求，加锁防重复。\n\n### 图示\n\n```mermaid\nflowchart LR\n    C[\"客户端<br/>记录最小序号\"] --> G[\"消息服务<br/>鉴权 会话校验\"]\n    G --> R{\"Redis最近两百条\"}\n    R -->|\"命中\"| C\n    R -->|\"未命中\"| S[\"存储层<br/>会话标识加反向序号\"]\n    S --> P[\"按序号倒序取一页\"]\n    P --> C\n    W[\"发送消息\"] --> Q[\"分配会话内序号\"]\n    Q --> S\n    Q --> R\n```\n\n### 关键选型与取舍\n\n- **游标还是偏移量**：选游标，偏移量在十万条时要先扫前面全部数据；放弃跳页，需要时改用时间锚点。\n- **反向还是正序存储**：选反向，绝大多数请求取最近一页；放弃正序范围扫描的便利，导出场景单独走离线。\n- **缓存最近还是全量**：选只缓存最近两百条，内存随会话数线性增长；放弃全量命中，冷数据回源可接受。\n- **分库分表**：按会话分 64 片保证同会话有序；放弃按用户分片，否则群聊消息要复制多份。\n\n### 风险与兜底\n\n- **序号分配单点**：用分段号段预取，重启从号段最大值续发，避免回退导致重复。\n- **冷热迁移丢消息**：先双写再删除，窗口内合并新旧结果并按序号去重。\n- **缓存与库不一致**：缓存只作加速，未命中回源；序号断层立即告警并清理该会话缓存。\n\n### 面试加分点\n\n- 序号是支点：把分页从计数偏移变成范围比较，复杂度从线性降到对数级。\n- 压测按十万条会话连续下拉一百页测 P99，而不是只测首页。","sysd-018":"**一句话结论**：HashMap 非线程安全，并发写会丢数据甚至结构损坏；线程安全版走桶级锁加原子插入，无锁版走不可变快照加引用替换。\n\n### 约束与目标\n\n- 百万级键值，并发 16 到 64 线程，读远多于写，读 P99 要求微秒级。\n- 目标：写不丢、结构不坏、读可见，迭代期间允许弱一致。\n- 不做什么：不做持久化与事务语义，不保证迭代顺序稳定。\n\n### 拆解思路\n\n1. **先定语义**：明确支持哪些操作、迭代是否要强一致、能否接受中间态，这决定用锁还是无锁。\n2. **锁方案**：空桶比较并交换插入，非空桶锁住桶头；扩容用转发节点让读写自动路由新旧表。\n3. **无锁方案**：写时复制整表再原子替换根引用，或用持久化树只复制路径节点再换根。\n4. **计数与扩容**：容量用分离热点的累加器；扩容多线程协助迁移，或直接换表后回收旧表。\n\n### 图示\n\n```mermaid\nflowchart TD\n    A[\"操作入口\"] --> B{\"读还是写\"}\n    B -->|\"读\"| C[\"无锁读<br/>volatile节点\"]\n    B -->|\"写\"| D[\"计算桶下标\"]\n    D --> E{\"桶是否为空\"}\n    E -->|\"空\"| F[\"比较并交换放入首节点\"]\n    E -->|\"非空\"| G[\"锁住桶头\"]\n    G --> H[\"链表或红黑树插入\"]\n    H --> I{\"超过负载因子\"}\n    I -->|\"是\"| J[\"多线程协助扩容<br/>转发节点\"]\n    I -->|\"否\"| K[\"累加器更新容量\"]\n```\n\n### 关键选型与取舍\n\n- **分段锁还是桶级锁**：选桶级，粒度更细、并发随桶数增长；代价是迁移复杂，写少表小用分段更简单。\n- **加锁还是写时复制**：选加锁，写不会消失，复制带来内存与回收压力；读远多于写且表很小时才选复制。\n- **弱一致迭代还是加锁快照**：选弱一致不阻塞写；需要稳定视图时复制键数组再遍历。\n- **计数实现**：选高并发累加器，单个原子变量在 64 线程下自旋失败率很高。\n\n### 风险与兜底\n\n- **扩容期读越界**：转发节点把请求导向新表；负载因子取 0.75，预留空间减少连续扩容。\n- **死锁**：只锁单个桶头，禁止多锁嵌套；必须多锁时按哈希值排序加锁。\n- **可见性**：节点值声明 volatile，发布新表用 volatile 写保证释放语义。\n- **复制方案写放大**：监控回收频率与内存峰值，写比例超三成切回锁方案。\n\n### 面试加分点\n\n- 说得出具体表现：旧版本头插法并发扩容成环打满 CPU，新版本并发写直接丢数据。\n- 压测口径 16 线程读写各半，对比吞吐与 P99，而不是只报单线程基准。","sysd-019":"**一句话结论**：购物车以 Redis 哈希为主存、数据库异步落盘，商品信息实时回查，未登录本地存，登录后按商品取大合并。\n\n### 约束与目标\n\n- 日活百万，单用户 50 到 200 个商品项，读远多于写，列表一天打开约十次。\n- 目标：加购 P99 小于 200ms，多端一致，失效商品可见但不参与结算。\n- 不做什么：不做结算与优惠计算，也不做跨店铺分组排序。\n\n### 拆解思路\n\n1. **存储模型**：按用户存哈希，字段是商品标识，值是数量、选中与加购时间；数据库留一份供持久化与客服查询。\n2. **加购链路**：先校验上下架、限购与库存，再原子累加数量，超单用户上限拒绝并提示清理。\n3. **列表聚合**：一次取出全部项，批量查价格、库存、标签后合并，下架商品标记失效而非删除。\n4. **多端与落盘**：登录端共享服务端数据；未登录本地存，登录时按商品取较大数量合并；变更发消息异步落库对账。\n\n### 图示\n\n```mermaid\nflowchart LR\n    U[\"客户端 App 小程序 网页\"] --> A[\"购物车服务<br/>鉴权 限频\"]\n    A --> V{\"商品校验<br/>上下架 限购 库存\"}\n    V -->|\"无效\"| X[\"返回失败原因\"]\n    V -->|\"有效\"| R[\"Redis哈希<br/>用户维度商品项\"]\n    R --> M[\"发送变更事件\"]\n    M --> D[\"消费者幂等落库\"]\n    R --> L[\"列表聚合<br/>批量查价格库存\"]\n    L --> U\n```\n\n### 关键选型与取舍\n\n- **Redis 主存还是库主存**：选 Redis 加异步落盘，读写高频且天然是映射结构；放弃强持久化，绝不丢时改双写。\n- **价格快照还是实时查**：选实时查，快照会误导用户；代价是多一次批量调用，可用并行压成一次往返。\n- **失效商品删还是留**：选标记保留便于回购；代价是列表过滤与清理，三十天未变动自动清除。\n- **合并策略**：选按商品取较大数量，放弃以某一端为准，避免多端加购被覆盖。\n\n### 风险与兜底\n\n- **Redis 丢数据**：每秒刷盘加异步落库，重启从库重建，丢失窗口内提示重试。\n- **消息积压**：超阈值降级同步写库并限流，优先保证下单前的数据可见。\n- **超限刷车**：单用户限频、单项上限固定，超限返回明确错误码而不是静默截断。\n\n### 面试加分点\n\n- 购物车不是账本：允许最终一致与快速失败，强校验放在下单链路。\n- 容量估算：百万用户人均百项、单条约 200 字节，整体约百 GB，需按用户分片。","sysd-020":"**一句话结论**：订单同步按贴源分层、增量优先、幂等写入、日终对账落地，准确靠可重跑与对账，性能靠抽取限速与批量提交。\n\n### 约束与目标\n\n- 日订单 300 万，存量约 10 亿，报表以 T+1 为主，看板要求小时级。\n- 目标：订单数与成交额与交易库完全对齐，同步不影响线上交易，日增量一小时内完成。\n- 不做什么：不做秒级实时大屏，也不在同步链路做业务口径计算。\n\n### 拆解思路\n\n1. **分层建模**：贴源保原始、明细清洗去重、汇总预聚合、应用只服务固定报表，每层可单独重跑。\n2. **抽取**：存量按主键区间分批，每批五千并限速走从库；增量优先解析日志变更，无权限用更新时间水位线。\n3. **传输落库**：消息按订单标识分区保同单有序，主键覆盖并按版本号取较大值，重复消费天然幂等。\n4. **校验与性能**：每层做主键唯一与金额校验，日终对账落差异表；列存按天分区，报表走宽表。\n\n### 图示\n\n```mermaid\nflowchart LR\n    DB[\"交易库\"] --> O[\"贴源层\"]\n    DB --> C[\"日志变更解析\"]\n    DB --> B[\"存量分批抽取<br/>从库限速\"]\n    C --> Q[\"消息队列<br/>按订单标识分区\"]\n    B --> Q\n    Q --> W[\"明细层<br/>幂等覆盖写入\"]\n    W --> S[\"汇总层\"]\n    S --> A[\"报表层\"]\n    W --> K[\"日终对账<br/>差异表\"]\n```\n\n### 关键选型与取舍\n\n- **日志变更还是定时拉取**：选日志变更，能捕获更新删除且延迟低；代价是运维复杂与表结构调整，无权限退回水位线。\n- **全量重跑还是分区增量**：选增量加指定分区重跑，十亿级全量成本高；放弃实现简单，口径变更只重算受影响分区。\n- **精确一次还是至少一次加幂等**：选后者，跨异构系统精确一次代价过高；放弃零重复，用对账保证结果正确。\n\n### 风险与兜底\n\n- **大促写入洪峰**：按订单标识限速消费，积压超两小时告警，必要时降级 T+1 离线补数保报表。\n- **位点丢失**：位点每十秒持久化，重启续传，重复由幂等吸收，禁止跳位点。\n- **金额不一致**：日终差异超万分之一阻断报表发布并告警，按订单重跑该分区。\n\n### 面试加分点\n\n- 对账是验收标准而非补充手段，差异表要能定位到具体订单并一键重跑。\n- 量级换算：300 万每天约 35 TPS，峰值几百，瓶颈在抽取与落库批量，不在消息队列。","sysd-021":"**一句话结论**：用日志变更捕获加消息队列解耦，消费端批量幂等写湖表，靠位点与检查点续传，端到端延迟控制在十秒内。\n\n### 约束与目标\n\n- 日均五亿行变更，涉及两百多张表，端到端延迟小于十秒。\n- 目标：不丢数据、重复可被覆盖，采集不影响主库，表结构变更不阻断整体链路。\n- 不做什么：不做跨机房双活，也不做业务字段的实时加工计算。\n\n### 拆解思路\n\n1. **采集**：从只读从库解析日志变更，记录文件名与位点；多实例按库或表分配，避免单点。\n2. **传输**：按表分主题、按主键哈希分区保证同主键有序，消息带操作类型、变更前后镜像与位点。\n3. **写入**：按主键覆盖，攒批一千条或五秒提交一次，减少小文件与提交开销，湖表按天分区。\n4. **一致性与运维**：先写数据文件再提交位点形成检查点，恢复从检查点续跑；以位点差值作为延迟指标。\n\n### 图示\n\n```mermaid\nflowchart LR\n    M[\"MySQL主库\"] --> R[\"只读从库\"]\n    R --> C[\"日志变更采集<br/>记录位点\"]\n    C --> K[\"消息队列<br/>按表分区\"]\n    K --> F[\"消费端<br/>主键覆盖写入\"]\n    F --> H[\"湖表<br/>攒批一千条五秒\"]\n    H --> D[\"数仓查询\"]\n    C --> L[\"延迟监控<br/>位点差\"]\n    L --> A[\"告警与限流\"]\n```\n\n### 关键选型与取舍\n\n- **日志变更还是业务双写**：选日志变更，零侵入且能捕获删除；放弃双写的低延迟，双写只在无法读日志时作补偿。\n- **消息队列还是直连写入**：选队列解耦，放弃几毫秒极致延迟，换削峰、多下游复用与可回放。\n- **湖表还是直接写实时数仓**：选支持行级更新的湖表，更新删除是常态；以追加为主且要秒级时可选替换引擎。\n\n### 风险与兜底\n\n- **日志过期被清理**：位点落后超过保留期即告警，触发该表全量重灌，期间标记数据不可用。\n- **表结构变更**：加列自动透传，删列与改类型阻断告警，人工确认后从变更点重放。\n- **消费积压**：延迟超一百万条扩容消费者，仍不下降则暂停低优先级表，优先核心交易表。\n\n### 面试加分点\n\n- 延迟能分解：采集一秒、传输一秒、攒批五秒、提交一秒，加起来才对得上十秒 SLA。\n- 用位点差值量化延迟，比说近实时更可信，也方便设告警阈值。","sysd-022":"**一句话结论**：状态外置、实例可替换、故障靠选主与幂等，容错核心是重试有上限、失败有死信、结果有对账。\n\n### 约束与目标\n\n- 跨机房部署，任务五千条，日同步 10TB，恢复点目标一分钟、恢复时间目标五分钟。\n- 目标：任一实例、中间件单节点或目标库短暂不可用，都不丢数据、不重复计数。\n- 不做什么：不做业务事务编排，也不承诺跨机房零数据丢失。\n\n### 拆解思路\n\n1. **拓扑冗余**：采集主备，队列三副本跨机架，消费无状态多副本，元数据主从加定时备份。\n2. **状态外置**：位点、配置、心跳全存元数据存储，实例无本地关键状态，随时可杀掉替换。\n3. **故障检测**：心跳三秒一次，连续三次判死；主备靠租约选主，续约失败主动退出防双主。\n4. **写入与补偿**：幂等键加本地事务，失败退避重试三次进死信；定时对账差异自动重灌。\n\n### 图示\n\n```mermaid\nflowchart LR\n    S[\"业务源库\"] --> P[\"采集主实例<br/>租约选主\"]\n    P --> K[\"消息队列三副本\"]\n    K --> C[\"消费组<br/>无状态多副本\"]\n    C --> T[\"目标库<br/>幂等覆盖写入\"]\n    C -.->|\"三次失败\"| DL[\"死信队列\"]\n    P -.->|\"心跳三秒\"| MD[\"元数据存储<br/>位点 配置 租约\"]\n    MD --> RC[\"对账任务<br/>差异重灌\"]\n    T --> RC\n```\n\n### 关键选型与取舍\n\n- **主备还是双活多写**：选主备加租约，双活要全局去重复杂度高；放弃秒级无缝切换，接受分钟级，下游强幂等再考虑双活。\n- **有限重试还是无限重试**：选三次后死信加人工补偿，放弃自动自愈的省心，避免毒消息阻塞整个分区。\n- **精确一次还是至少一次加幂等**：选后者，异构存储精确一次不可靠；放弃理论最优，换工程可验证。\n\n### 风险与兜底\n\n- **双主同时消费**：租约带过期，续约失败即停止拉取；下游幂等保证重复不翻倍并告警脑裂。\n- **队列副本不足**：副本数低于二暂停消费并告警，禁止降级到单副本裸奔。\n- **目标库长时间不可用**：本地磁盘缓冲上限一小时，超限暂停采集并告警，避免拖垮磁盘。\n\n### 面试加分点\n\n- 恢复指标用演练背书：杀实例、断网、摘分区各跑一次，记录真实恢复点与恢复时间。\n- 可观测四件套：位点延迟、消费速率、死信量、对账差异，每项都要面板与阈值告警。","sysd-023":"**一句话结论**：网关用非阻塞转发扛吞吐，路由放配置中心靠订阅推送生效，限流本地令牌桶加全局配额校正，自身多实例无状态。\n\n### 约束与目标\n\n- 入口峰值 10 万 QPS，后端两百个微服务，路由规则上千条且每天有变更。\n- 目标：转发额外延迟 P99 小于 10ms，规则十秒内生效，实例故障对业务无感。\n- 不做什么：不做业务编排与数据聚合，也不做服务间东西向流量治理。\n\n### 拆解思路\n\n1. **功能盘点**：路由转发、协议转换、统一鉴权、限流熔断、灰度版本、日志追踪、跨域缓存，按优先级排期。\n2. **接入层**：非阻塞 IO 与连接池复用后端，减少握手；长连接单独通道，避免阻塞短请求。\n3. **动态路由**：规则存配置中心，网关订阅推送，本地前缀树做第一层匹配，少量通配用正则兜底。\n4. **限流与高可用**：本地令牌桶按实例配额，全局配额定时校正；实例无状态加健康检查，拉取失败用本地快照。\n\n### 图示\n\n```mermaid\nflowchart LR\n    C[\"客户端\"] --> LB[\"负载均衡\"]\n    LB --> GW[\"网关实例集群\"]\n    GW --> F1[\"鉴权与签名校验\"]\n    F1 --> F2{\"前缀树路由匹配\"}\n    F2 --> F3[\"限流与熔断\"]\n    F3 --> F4[\"协议转换与转发\"]\n    F4 --> S[\"后端微服务\"]\n    CFG[\"配置中心<br/>路由与限流规则\"] -.->|\"订阅推送\"| F2\n    CFG -.->|\"订阅推送\"| F3\n    GW --> OBS[\"日志 链路追踪 指标\"]\n```\n\n### 关键选型与取舍\n\n- **自研还是成熟网关**：优先成熟网关，插件生态与运维成熟；只有极致性能或特殊协议才自研，代价是长期维护成本。\n- **推送还是轮询**：选订阅推送加三十秒兜底轮询，放弃零延迟强一致，换断连自愈与实现简单。\n- **前缀树还是正则遍历**：选前缀树，上千条正则逐条匹配会成为延迟瓶颈；放弃绝对灵活。\n\n### 风险与兜底\n\n- **规则推空或推错**：先灰度一台观察两分钟，规则带版本可回滚，解析失败回退上一版快照。\n- **单实例过载**：连接数与 QPS 双阈值，超限拒绝新连接，健康检查失败自动摘除。\n- **后端慢拖垮连接池**：按路由配 500ms 超时与熔断，快速失败返回兜底，避免线程耗尽雪崩。\n\n### 面试加分点\n\n- 延迟拆开讲：TLS 约 1ms、路由匹配小于 1ms、转发 3ms，其余是后端耗时，便于定位瓶颈。\n- 网关既是控制面也是数据面，规则变更必须走灰度与审计。","sysd-024":"**一句话结论**：版本用路径标识、路由表按方法路径版本三维匹配，能由适配层消化的小变更不开新版本，灰度按用户打标看调用量下线。\n\n### 约束与目标\n\n- 三百个接口、三个版本并行，生命周期六到十二个月，客户端不允许大改造。\n- 目标：未声明版本的请求有确定默认行为，切换可按用户灰度且三十秒内回滚。\n- 不做什么：不做字段级内容协商，也不长期维护超过三个并行版本。\n\n### 拆解思路\n\n1. **版本标识**：对外统一用路径前缀，直观且便于负载均衡与日志区分；内部调用用请求头避免路径污染。\n2. **路由模型**：路由键由方法、路径、版本组成，未带版本按默认策略补全再匹配后端。\n3. **兼容策略**：优先适配层，把旧请求转成统一内部模型做字段补齐裁剪；语义破坏才维护双实现。\n4. **灰度与下线**：按用户租户打标并透传版本上下文；废弃版本返回下线提示头，调用量降到阈值再摘除。\n\n### 图示\n\n```mermaid\nflowchart LR\n    C[\"客户端 v1 v2 v3\"] --> G[\"网关<br/>解析版本标识\"]\n    G --> D{\"路由表<br/>方法 路径 版本\"}\n    D -->|\"v1\"| A1[\"v1适配层<br/>请求转换\"]\n    D -->|\"v2\"| A2[\"v2实现\"]\n    D -->|\"v3\"| A3[\"v3实现\"]\n    A1 --> I[\"统一内部模型\"]\n    A2 --> S[\"领域服务\"]\n    A3 --> S\n    I --> S\n    G --> M[\"版本调用量监控<br/>灰度与下线\"]\n```\n\n### 关键选型与取舍\n\n- **路径版本还是请求头版本**：选路径，可缓存可读且日志可区分；放弃地址不变的优雅，内部调用再用请求头。\n- **适配层还是双实现**：选适配层省人力；放弃彻底隔离的简单性，语义差异过大时只能双实现。\n- **默认版本行为**：选未声明走最新稳定版加灰度名单，放弃一律拒绝的严格，换平滑迁移。\n\n### 风险与兜底\n\n- **版本与实例错配**：网关校验请求结构与实例标签，不匹配直接拒绝并告警。\n- **灰度误伤大客户**：按内部账号、百分之一、一成、全量阶梯推进，每步看错误率与 P99。\n- **旧版本被遗忘**：监控各版本调用量，废弃三十天强制告警，九十天未清零则下线并通知调用方。\n\n### 面试加分点\n\n- 版本是契约不是目录，适配层能消除的变更不要开新版本，否则接口数量会失控。\n- 下线决策靠数据：每版本 QPS、错误率、调用方清单三项齐全才允许摘除。","sysd-025":"**一句话结论**：时间戳、一次性随机数、签名三件套，随机数在窗口内只落一次，业务再叠幂等键，缓存故障宁可误杀。\n\n### 约束与目标\n\n- 开放接口日均一亿次，攻击者可抓包重放，合法请求额外延迟小于 5ms。\n- 目标：同一请求十分钟内只能成功一次，拦截率接近百分之百，不影响正常客户端。\n- 不做什么：不强制双向证书，也不要求所有客户端改造加密协议。\n\n### 拆解思路\n\n1. **威胁建模**：HTTPS 防窃听，但客户端环境与日志仍可能泄露完整请求，需在应用层做一次性与完整性校验。\n2. **签名**：对方法、路径、请求体摘要、时间戳、随机数做 HMAC，密钥按应用分发并可轮换。\n3. **时间窗**：服务端校验时间戳偏差不超过五分钟，超出拒绝，压缩可重放窗口。\n4. **去重与幂等**：随机数写 Redis 并设十分钟过期，写入失败即判重放；写接口带客户端标识，库里唯一索引兜底。\n\n### 图示\n\n```mermaid\nsequenceDiagram\n    participant C as 客户端\n    participant G as 网关\n    participant R as Redis\n    participant S as 业务服务\n    C->>G: 请求 含签名 时间戳 随机数\n    G->>G: 校验时间窗与签名\n    G->>R: 写入随机数并设过期\n    alt 已存在\n        R-->>G: 写入失败\n        G-->>C: 拒绝 判定为重放\n    else 首次\n        R-->>G: 写入成功\n        G->>S: 转发请求\n        S-->>G: 处理结果\n        G-->>C: 返回响应\n    end\n```\n\n### 关键选型与取舍\n\n- **随机数加时间戳还是只用时间戳**：选前者，否则窗口内可反复重放；代价是每请求一次缓存写，日均一亿约每秒千余次。\n- **集中去重还是本地**：选集中，跨实例共享；单机网关可本地缓存加布隆过滤器，牺牲准确性换延迟。\n- **一律拒绝还是返回上次结果**：查询类选拒绝；支付类写接口可返回上次结果，体验更好但要额外保存响应。\n\n### 风险与兜底\n\n- **Redis 不可用**：降级本地缓存并把窗口缩到一分钟，同时告警；高危接口直接拒绝，宁可误杀不可放过。\n- **时钟漂移**：服务端间做时间同步，偏差超三十秒的请求记录并采样上报，避免窗口判断失效。\n- **边界压线**：随机数过期长于时间窗两倍以覆盖边界，每小时统计重复命中率，异常接风控。\n\n### 面试加分点\n\n- 算成本：一亿每日乘十分钟窗口约七百万键、内存约 1GB，是落地关键数字。\n- 防重放与幂等是一体两面：前者防报文二次进入，后者防业务被重复执行。","sysd-026":"**一句话结论**：配置中心用版本化存储加审批发布、客户端长轮询加本地快照，变更分批灰度，一秒生效且可一键回滚。\n\n### 约束与目标\n\n- 五百个服务实例，配置项上万，单次变更要求一秒内生效到全量实例。\n- 目标：错误配置可自动回滚，变更可审计可追溯，客户端断连不影响已加载配置。\n- 不做什么：不做通用服务注册发现，也不支持运行时修改任意代码级参数。\n\n### 拆解思路\n\n1. **配置建模**：按应用、分组、键三层组织，带版本与灰度标签；区分启动配置与可热更新项，后者才允许运行时改。\n2. **存储与发布**：版本与审计存库，发布走发布单加审批，每次生成不可变版本，可按版本回滚。\n3. **推送机制**：客户端长轮询，服务端挂起三十秒，变更即返回；收到后按版本拉增量，失败回退全量。\n4. **生效与灰度**：客户端构造新对象原子替换引用再触发回调；按实例标签先一台、再一成、最后全量。\n\n### 图示\n\n```mermaid\nflowchart LR\n    O[\"运维提交变更\"] --> API[\"配置服务<br/>校验 审批 生成版本\"]\n    API --> DB[\"版本库<br/>审计记录\"]\n    API --> W[\"长轮询挂起<br/>有变更立即唤醒\"]\n    W --> C1[\"实例A<br/>本地快照与增量\"]\n    W --> C2[\"实例B<br/>本地快照与增量\"]\n    C1 --> H[\"配置持有者<br/>原子替换引用\"]\n    C1 -.->|\"三十秒兜底\"| API\n    H --> B[\"业务组件刷新\"]\n```\n\n### 关键选型与取舍\n\n- **长轮询还是长连接**：选长轮询，兼容好、断线重连、实现简单；放弃毫秒级即时性，一秒已够，极低延迟才用流式。\n- **增量还是全量拉取**：选版本号加增量，失败回退全量；放弃实现简单，换带宽与解析成本。\n- **本地快照还是纯远程读取**：选快照，配置中心必须可挂；代价是处理快照过期与一致性。\n\n### 风险与兜底\n\n- **错误配置全量生效**：强制灰度加发布前校验，变更后一分钟内错误率或负载突增自动回滚。\n- **漏推实例**：客户端三十秒兜底轮询加启动全量拉取，服务端维护未确认实例清单并告警。\n- **配置中心不可用**：客户端用快照继续运行只读不改，恢复后按版本对齐防旧值覆盖新值。\n\n### 面试加分点\n\n- 配置与开关分开，开关走独立灰度通道，避免一次发布变成全站变更。\n- 生效口径量化：变更到全量 P99 小于一秒，靠挂起加变更唤醒实现。","sysd-027":"**一句话结论**：配置中心是控制面，业务面不能依赖它活着：内存配置、本地快照、镜像默认值三级兜底，降级期禁止高危变更。\n\n### 约束与目标\n\n- 配置中心整体不可用时，新实例必须能启动，存量实例必须能继续服务。\n- 目标：启动成功率百分之百，降级期业务无错误，配置变更可延迟但不可错乱。\n- 不做什么：不做离线写入配置，也不在降级期执行自动化变更。\n\n### 拆解思路\n\n1. **三级兜底**：先用内存中最后有效配置，再用本地快照，最后用镜像内置默认值，逐级降级并标明级别。\n2. **启动路径**：先读快照并校验摘要，失败或缺失用默认值，禁止用写了一半的文件启动。\n3. **运行路径**：连不上则退避重连，间隔从一秒到三十秒封顶；不阻塞业务线程，继续用旧配置。\n4. **安全阀与恢复**：降级期只读，限流阈值与开关等高危项拒绝生效；恢复后只有服务端版本更高才覆盖。\n\n### 图示\n\n```mermaid\nflowchart TD\n    S[\"服务启动\"] --> A{\"内存中有配置\"}\n    A -->|\"有\"| U[\"直接使用\"]\n    A -->|\"无\"| B{\"本地快照校验通过\"}\n    B -->|\"通过\"| U2[\"加载快照<br/>标记降级\"]\n    B -->|\"失败\"| C[\"使用镜像内置默认值<br/>安全值\"]\n    U --> R[\"运行中\"]\n    U2 --> R\n    C --> R\n    R --> W{\"配置中心可达\"}\n    W -->|\"不可达\"| D[\"退避重连<br/>只读禁止高危变更\"]\n    W -->|\"可达\"| E[\"版本比对<br/>仅接受更高版本\"]\n```\n\n### 关键选型与取舍\n\n- **本地快照还是启动强依赖**：选快照，放弃配置绝对新鲜换可用性；强一致场景可改启动强校验并接受启动失败。\n- **可用优先还是不明就不启动**：选可用优先，但默认值必须是安全值，比如限流收紧、开关关闭。\n- **快照是否过期**：选不过期按版本驱动，放弃 TTL，避免长期不可用时配置凭空消失。\n\n### 风险与兜底\n\n- **快照损坏**：启动校验摘要，失败回退内置默认值并告警，禁止解析半截文件。\n- **长期降级配置漂移**：降级超三十分钟升级高优告警，超两小时建议摘流重启并重新拉取。\n- **恢复打挂配置中心**：客户端加零到三十秒随机抖动，服务端分批放量，避免二次雪崩。\n\n### 面试加分点\n\n- 一句话把边界讲清：控制面失效不等于数据面失效。\n- 验证方式具体：杀掉配置中心，观察新实例启动、老实例服务、恢复后是否平滑。","sysd-028":"**一句话结论**：状态机驱动、库存 TCC 预占、状态变更走本地消息表、悬挂靠定时补偿与对账，换不超卖不重复扣款。\n\n### 约束与目标\n\n- 下单峰值每秒一万笔，跨订单、库存、支付三个服务与三个库。\n- 目标：库存绝不超卖，支付不重复扣款，订单最终一致且不允许长时间悬挂。\n- 不做什么：不做跨行转账级强一致，也不引入同步阻塞的全局两阶段提交。\n\n### 拆解思路\n\n1. **拆边界**：下单只创建待支付订单并预占库存；支付回调实扣并置已支付；超时任务释放库存并关单，每步本地事务。\n2. **状态机**：订单只允许待支付、已支付、已关闭、退款中按固定边跃迁，非法跃迁拒绝，天然防重复。\n3. **库存 TCC**：预占冻结、确认转已售、取消解冻；预占记录带过期时间防长期占用。\n4. **消息与补偿**：状态变更与消息同事务写消息表，投递任务扫表发送，消费端按订单号加操作类型幂等；定时补偿加日终对账。\n\n### 图示\n\n```mermaid\nflowchart LR\n    U[\"用户下单\"] --> O[\"订单服务<br/>创建待支付订单\"]\n    O --> I[\"库存服务<br/>预占冻结\"]\n    I -->|\"成功\"| P[\"支付服务<br/>拉起支付\"]\n    I -->|\"失败\"| X[\"下单失败\"]\n    P --> CB[\"支付回调<br/>幂等校验\"]\n    CB --> C[\"库存确认实扣\"]\n    CB --> S[\"订单置为已支付\"]\n    O --> OB[\"本地消息表<br/>同事务写入\"]\n    OB --> MQ[\"投递任务发送\"]\n    T[\"超时关单任务\"] --> CC[\"库存取消释放\"]\n    T --> CL[\"订单关闭\"]\n    RC[\"日终对账<br/>渠道流水与订单\"] --> CB\n```\n\n### 关键选型与取舍\n\n- **TCC 还是 Saga**：库存选 TCC，超卖需强隔离；放弃零侵入，积分通知这类后置步骤用 Saga。\n- **本地消息表还是事务消息**：选消息表，不绑定中间件且可重放；代价是扫表与毫秒延迟，原生事务消息可省表。\n- **同步校验还是全异步**：核心链路同步校验库存再异步后续，放弃全异步的简单，换用户即时反馈。\n\n### 风险与兜底\n\n- **支付成功订单未更新**：回调加主动查单双通道，五分钟未更新自动补偿，超时告警并人工介入。\n- **预占未释放少卖**：预占带过期时间，关单与扫描双保险，异常预占计入指标告警。\n- **重复扣款或发货**：支付单号唯一索引，发货前校验状态机只允许一次跃迁，重复返回上次结果。\n\n### 面试加分点\n\n- 骨架：状态机防乱序、幂等键防重复、对账防遗漏，缺一层就有悬挂单。\n- 阈值：悬挂订单占比超千分之一触发值班，所有补偿动作必须可重入。","sysd-029":"**一句话结论**：补偿不是失败后重调接口，而是本地消息表保证必达、幂等状态机保证不重复、T+1 对账兜底的最终一致方案。\n\n### 约束与目标\n\n- 跨 3 到 5 个微服务，日事务百万级，链路 QPS 数百，可接受分钟级最终一致。\n- 底线是不丢单、不重复扣款，补偿动作必须可逆且可重入。\n- 不做 TCC 全套改造，业务方只提供反向接口。\n- 目标：自动补偿成功率 99.9% 以上，未闭环由 T+1 对账全量发现。\n\n### 拆解思路\n\n1. **先确认补偿能力**：把正向动作的逆操作定义成幂等接口，如退款、释放库存、撤积分，没有可逆动作就不进链路。\n2. **本地消息表保证必达**：事务表与业务数据同库同事务写入，再由投递任务或 CDC 送到 MQ。\n3. **状态机推进**：状态按 pending、executing、compensating、closed 流转并落库，重启可续跑；失败按秒级、5 分钟、30 分钟、2 小时退避，24 小时未闭环转人工。\n4. **对账兜底**：T+1 拉各参与方流水逐笔比对事务表，产出两类差异单。\n\n### 图示\n\n```mermaid\nflowchart LR\n    BIZ[\"业务写库<br/>业务数据与事务表同事务\"] --> OUT[\"本地消息表 Outbox\"]\n    OUT --> MQ[\"消息队列\"]\n    MQ --> COMP[\"补偿执行器<br/>幂等状态机\"]\n    COMP --> ST[\"事务状态表<br/>pending 到 closed\"]\n    COMP -->|\"失败\"| DLY[\"延迟队列<br/>5min 30min 2h\"]\n    DLY --> COMP\n    COMP -->|\"超 24 小时\"| TK[\"人工工单\"]\n    ST --> RECON[\"T+1 对账<br/>流水逐笔比对\"]\n    RECON -->|\"差异单\"| TK\n```\n\n### 关键选型与取舍\n\n- **Outbox 而不是 TCC**：改造量小、不冻结资源，代价是存在分钟级不一致窗口；资金冻结这类强一致场景仍应选 TCC。\n- **状态机而不是无限重试**：避免同一补偿反复执行，代价是状态都要可查、可人工推进。\n- **独立对账而不是相信消息**：消息会丢会乱序，只有流水比对能发现资损，代价是要各系统开放流水查询。\n\n### 风险与兜底\n\n- 重复补偿导致重复退款：以事务 ID 加子动作做唯一键落库，重复请求返回上次结果。\n- 重试打爆下游：按参与方限流并熔断，失败转延迟队列，恢复后按时间片回放。\n- 消息丢失或乱序：定时扫表补投 pending 超 3 分钟记录，消费端按版本号丢弃旧状态。\n- 长期不闭环：超 24 小时未终态即告警开工单，差异单日结清零。\n\n### 面试加分点\n\n- 补偿第一问是每个动作能不能撤销，不能撤销的要提前设计成可冲正。\n- 把一致性做成可查询的事务单据，比口头保证更能说服面试官。","sysd-030":"**一句话结论**：一致性 Hash 用哈希环加虚拟节点，把节点增减的迁移量从全量降到约 1/N，真正要治理的是均衡度与热点 key。\n\n### 约束与目标\n\n- 缓存集群 10 到 50 台，扩缩容与宕机都会改变节点集合，key 亿级。\n- 节点变更时迁移量要控制在 1/N 量级，不能全量失效引发击穿。\n- 各节点 key 数偏差控制在 15% 以内。\n- 不追求严格均匀，但不能出现单点热点。\n\n### 拆解思路\n\n1. **构造哈希环**：0 到 2 的 32 次方首尾相接成环，节点按 ip 加端口哈希落环，key 哈希后顺时针找第一个节点。\n2. **加虚拟节点**：每台物理机映射 100 到 200 个虚拟节点，解决节点数少时环上分布不均，副本越多越均衡。\n3. **算迁移范围**：key 只归属顺时针第一个节点，某节点下线只影响它与前一节点之间区间，迁移量约 1/N。\n4. **扩容预热**：新节点先按区间回源拉数据再切流量，避免打到数据库。\n5. **客户端兜底**：本地缓存环结构并带版本号，节点失败时重试顺时针下一个节点。\n\n### 图示\n\n```mermaid\nflowchart LR\n    KEY[\"缓存 key\"] --> H1[\"hash 取模 2 的 32 次方\"]\n    H1 --> RING[\"哈希环<br/>0 到 2^32\"]\n    RING --> VN[\"虚拟节点<br/>每台 150 个\"]\n    VN --> N1[\"物理节点 A\"]\n    VN --> N2[\"物理节点 B\"]\n    VN --> N3[\"物理节点 C\"]\n    N1 -->|\"宕机\"| N2\n    N2 -->|\"失败重试\"| NEXT[\"顺时针下一个节点\"]\n    CLI[\"客户端环缓存<br/>版本号推送\"] --> RING\n```\n\n### 关键选型与取舍\n\n- **虚拟节点 150 个左右而不是一节点一环**：均衡度更好，代价是环元数据变大，客户端内存占用上升但可忽略；节点极少时还要加大副本。\n- **客户端侧一致性 Hash 而不是中间代理**：少一跳、无单点，代价是环变更要广播到所有客户端；客户端难统一升级时改用代理分片。\n- **固定哈希函数而不是随机加盐**：结果稳定可复现，代价是天生打不散热点，热点 key 需业务层再拆。\n\n### 风险与兜底\n\n- 数据倾斜：监控各节点 key 数与内存，偏差超 15% 就加虚拟节点或做区间再平衡。\n- 节点宕机流量集中到顺时针下一个：失败重试跳过两个节点并加本地短缓存。\n- 环变更风暴：环版本分批推送，按 10%、50%、100% 放开，异常回滚版本。\n\n### 面试加分点\n\n- 一致性 Hash 解决的是节点变更时的迁移量，不是绝对负载均衡，均衡靠虚拟节点，热点靠业务拆分。\n- 可对比 Redis Cluster 的 16384 个槽，本质是固定分片加槽迁移。","sysd-031":"**一句话结论**：灰度是流量路由、分批放量、自动熔断三件套，关键是按用户稳定分桶而不是按比例随机。\n\n### 约束与目标\n\n- 服务上百实例、日活千万，核心接口 QPS 万级，发布窗口只有深夜几小时。\n- 要求分钟级放量与回滚，故障影响面控制在 5% 用户以内。\n- 灰度期新旧版本共存，接口与数据库变更必须向前兼容。\n\n### 拆解思路\n\n1. **稳定分桶**：网关按 uid 稳定哈希取模分桶，桶到版本映射持久化，用户不会在两版本间反复跳。\n2. **分批放量**：按 1%、5%、20%、50%、100% 五档推进，每档观察 10 到 30 分钟。\n3. **指标准入**：每批设红线，错误率超 1%、P99 翻倍、核心转化跌 20% 即判失败。\n4. **自动回滚**：失败时自动把路由表切回旧版本，只切流量不改数据。\n5. **数据兼容**：库变更只加列不删改，先双写再切读，代码回退后仍能读新数据。\n\n### 图示\n\n```mermaid\nflowchart LR\n    U[\"用户请求\"] --> GW[\"网关<br/>按 uid 稳定分桶\"]\n    GW --> RT[\"路由表<br/>桶到版本映射\"]\n    RT -->|\"1% 到 5%\"| V2[\"新版本实例\"]\n    RT -->|\"其余流量\"| V1[\"稳定版本实例\"]\n    V2 --> MET[\"指标采集<br/>错误率 P99 转化\"]\n    V1 --> MET\n    MET --> JUDGE[\"熔断判定<br/>连续 3 个采样点\"]\n    JUDGE -->|\"超阈值\"| RB[\"自动回滚<br/>路由切回旧版本\"]\n    JUDGE -->|\"正常\"| NEXT[\"下一批放量\"]\n```\n\n### 关键选型与取舍\n\n- **按 uid 分桶而不是纯随机比例**：体验一致、可复现、可定点排查，代价是要维护桶映射表；压测可用随机。\n- **网关统一路由而不是各服务自实现**：收敛一处、回滚快，代价是网关成为发布依赖，需多活部署。\n- **自动熔断而不是人工盯盘**：反应快，代价是阈值可能误判，需连续三个采样点超线才触发。\n- **双写过渡而不是蓝绿整机切换**：资源成本低，代价是双写不一致，蓝绿适合无状态服务。\n\n### 风险与兜底\n\n- 数据库变更不可回退：灰度期禁止删改字段，只允许加列加表，回滚只回代码。\n- 灰度样本不足导致指标失真：小比例按桶分配保证样本量，看板按版本拆分。\n- 熔断误判：排除上游故障导致的错误率上涨，连续采样确认后再回滚。\n- 回滚不彻底：镜像与配置版本化，保留旧版本实例 24 小时，脚本提前演练。\n\n### 面试加分点\n\n- 灰度难点在能不能回滚，发布前确认数据库变更可逆，比放量比例更重要。\n- 把分桶、红线、自动回滚固化成流水线，经验才变成可重复流程。","sysd-032":"**一句话结论**：SSO 是认证集中、会话分离，认证中心只发一次性票据，子系统用票据换自己的本地会话，日常请求不再回访中心。\n\n### 约束与目标\n\n- 10 到 30 个异构子系统，日活百万，登录 QPS 千级。\n- 要求一次登录访问全部子系统，支持单点登出，会话有效期 7 天。\n- 子系统只接 SDK 或拦截器，不做大改造。\n- 目标是登录成功率高，且中心压力与子系统数量解耦。\n\n### 拆解思路\n\n1. **统一身份源**：认证中心统一账号体系，登录成功后写全局会话，用 Cookie 或 token 标识。\n2. **一次性票据**：中心签发 60 秒有效、只能使用一次的 ticket，并绑定目标子系统。\n3. **子系统换票**：子系统带 ticket 回调中心校验，拿到身份后建本地会话，后续请求只验本地会话。\n4. **单点登出**：中心删除全局会话后广播登出事件，子系统清本地会话，未收到则等 TTL 自然失效。\n5. **跨域适配**：同父域共享 Cookie，跨域走 302 跳转，标准场景直接用 OIDC 协议。\n\n### 图示\n\n```mermaid\nsequenceDiagram\n    participant U as 用户浏览器\n    participant A as 子系统 A\n    participant C as 认证中心\n    participant R as 全局会话存储\n    U->>A: 访问受保护页面\n    A-->>U: 302 跳转认证中心\n    U->>C: 携带全局会话 Cookie\n    C->>R: 校验全局会话\n    R-->>C: 有效\n    C-->>U: 302 回跳并附一次性 ticket\n    U->>A: 携带 ticket 访问\n    A->>C: 服务端校验 ticket\n    C-->>A: 返回用户身份\n    A->>A: 建立本地会话\n    A-->>U: 返回页面\n    U->>C: 发起单点登出\n    C->>R: 删除全局会话并广播登出\n```\n\n### 关键选型与取舍\n\n- **票据换会话而不是共享 Session**：中心不必保存各子系统的会话，扩展性好，代价是首登多一次回调；子系统极少且同域时共享 Session 更省事。\n- **中心校验票据而不是子系统自解 JWT**：可即时吊销，代价是中心成为登录期强依赖；内网低风险场景可用 JWT 自校验换性能。\n- **集中认证而不是各系统各自登录**：体验统一，代价是中心故障影响全站，必须配降级方案。\n\n### 风险与兜底\n\n- 票据被截获重放：ticket 一次性、60 秒过期、绑定 clientIp 与 UA，重复使用即吊销全局会话。\n- 登出不同步：登出事件走 MQ 广播，加补偿表重放，本地会话 TTL 兜底。\n- 子系统伪造身份：ticket 只能服务端校验，禁止前端携带用户 ID 直接信任。\n\n### 面试加分点\n\n- SSO 管的是认证不是授权，权限留在各子系统，别把 RBAC 塞进中心。\n- 票据越短越安全，而用户登录态靠本地会话维持，两个生命周期要分开设计。","sysd-033":"**一句话结论**：已登录用户靠本地会话独立存活，中心只承担新登录，再叠加多活与分层降级，把故障影响收敛到暂时不能登录。\n\n### 约束与目标\n\n- 中心承载全站登录，故障影响百万在线用户。\n- 已登录会话必须继续可用，新登录允许短时不可用。\n- 会话不能因中心重启全部失效，恢复目标 5 分钟内。\n- 前提是日常请求链路不依赖中心实时校验。\n\n### 拆解思路\n\n1. **会话本地化**：已登录状态存在子系统本地或本地 Redis，请求路径不访问中心，这是零感知的根本。\n2. **弱依赖校验**：只在登录与续期时访问中心，日常请求只验本地会话或 JWT 签名。\n3. **中心多活**：两地多副本，前置网关做故障转移，会话落共享 Redis 而不是进程内存。\n4. **分层降级**：中心不可用时子系统切只读模式，禁止新登录，已登录操作照常。\n5. **恢复对齐**：中心恢复后通过会话同步接口补齐登出状态。\n\n### 图示\n\n```mermaid\nflowchart LR\n    U[\"已登录用户\"] --> S[\"子系统<br/>本地会话或 JWT\"]\n    S -->|\"日常请求不访问中心\"| OK[\"正常返回\"]\n    N[\"新登录用户\"] --> S\n    S -->|\"需要认证\"| C[\"认证中心\"]\n    C -->|\"故障\"| DG[\"降级模式<br/>禁止新登录\"]\n    DG --> P[\"页面提示维护中\"]\n    C --- REDIS[\"共享 Redis 集群<br/>多副本持久化\"]\n    C -->|\"恢复\"| SYNC[\"会话同步<br/>MQ 补齐登出状态\"]\n    SYNC --> S\n```\n\n### 关键选型与取舍\n\n- **本地会话而不是中心集中会话**：可用性高、无单点，代价是登出不能实时全局生效；金融级要求下应改中心强校验加短 TTL。\n- **多活而不是主备**：切换无感，代价是会话需共享存储、跨机房有延迟；成本敏感时主备加快切也可接受。\n- **只降级新登录而不是降级全部**：保住已登录体验，代价是故障期无法拉新，页面要明确提示。\n\n### 风险与兜底\n\n- 会话只存中心内存导致全丢：必须落 Redis 并开持久化，恢复后回放。\n- 双活脑裂导致互踢：会话写入带机房标识与版本号，冲突取时间戳新者。\n- 恢复瞬间流量洪峰：子系统排队加限流，登录放量按 10% 灰度放开。\n- 幽灵会话：登出事件落 MQ 补偿表，恢复后重放，TTL 最长 30 分钟兜底。\n\n### 面试加分点\n\n- 判断 SSO 健壮性的指标是中心宕机时已登录请求的成功率，设计按这个指标倒推。\n- 把认证中心当登录入口而不是每请求必经之路，是可用性设计的分水岭。","sysd-034":"**一句话结论**：签名解决篡改，时间戳加 nonce 解决重放，二者必须同时上；真正的难点在参数规范化，不在算法选择。\n\n### 约束与目标\n\n- 开放平台给第三方调用，QPS 千级，密钥按 appId 分发。\n- 攻击者能看到全部参数，可篡改、可重放、可伪造。\n- 客户端语言多样，签名算法要简单、各语言都易实现。\n- 目标：篡改必然验签失败，重放窗口压到 5 分钟以内。\n\n### 拆解思路\n\n1. **参数规范化**：按 key 字典序排序后拼成 key 等于 value 的串，空值、数组、编码规则写进文档，杜绝同一语义多种拼法。\n2. **计算签名**：用 HmacSHA256 对规范化串加 timestamp 加 nonce 计算，签名放 header，secret 永不上送。\n3. **防重放**：时间戳与服务端偏差超 5 分钟直接拒，nonce 以 appId 加 nonce 为键在 Redis 做 SETNX，TTL 为两倍窗口。\n4. **校验顺序**：先验 appId 有效，再验时间戳，再验 nonce，最后常量时间比对签名，全通过才进业务。\n5. **密钥治理**：secret 分环境隔离，支持新旧双密钥并存 7 天完成轮换，泄露可一键吊销。\n\n### 图示\n\n```mermaid\nflowchart LR\n    CL[\"客户端<br/>参数排序拼接\"] --> SG[\"计算 HmacSHA256<br/>参数加时间戳加 nonce\"]\n    SG --> GW[\"网关\"]\n    GW --> V1[\"校验 appId 有效\"]\n    V1 --> V2[\"校验时间戳偏差 5 分钟\"]\n    V2 --> V3[\"校验 nonce<br/>Redis SETNX 加 TTL\"]\n    V3 --> V4[\"常量时间比对签名\"]\n    V4 -->|\"通过\"| BIZ[\"业务服务\"]\n    V4 -->|\"失败\"| REJ[\"拒绝 401<br/>记录审计\"]\n```\n\n### 关键选型与取舍\n\n- **HMAC 对称而不是 RSA 非对称**：性能高、实现简单，代价是服务端持有 secret，泄露即可伪造；多租户开放平台可让客户端持私钥改 RSA。\n- **nonce 落 Redis 而不是只验时间戳**：能真正防重放，代价是每请求一次 Redis 写，高 QPS 时用本地 LRU 加 Redis 两层。\n- **签名放 header 而不是 body**：不参与参数排序、少踩坑，代价是网关必须透传 header。\n\n### 风险与兜底\n\n- 规范化歧义导致合法请求失败：文档固化，并提供多语言 SDK 与验签调试工具。\n- Redis 故障导致全量拒绝：nonce 校验降级为本地滑动窗口并告警，同时收紧业务限流。\n- 密钥泄露：按 appId 限流加异常调用监控，支持秒级吊销与双密钥轮换。\n- 客户端时钟漂移：响应返回服务器时间供校准，窗口放宽到正负 5 分钟。\n\n### 面试加分点\n\n- 对接问题九成出在参数规范化，空值、数组、URL 编码要写进契约，别让客户端猜。\n- 只有时间戳没有 nonce 的方案，在窗口内可被无限重放，这一点要主动点出来。","sysd-035":"**一句话结论**：传输靠 TLS 加应用层信封加密，存储靠字段级加密、密钥分层与展示脱敏，绝不自己发明算法，并提前为查询留盲索引。\n\n### 约束与目标\n\n- 身份证号、手机号等 PII 字段日写入百万级，读取更多。\n- 合规要求可审计可脱敏，密钥与数据分离存放。\n- 手机号需要支持精确查询，不能加密后查不了。\n- 目标是明文不出服务进程，日志与备份也不落明文。\n\n### 拆解思路\n\n1. **传输加密**：全链路 TLS 1.2 以上，内网也开启；高敏字段再叠应用层加密，防网关日志落明文。\n2. **字段级加密**：AES-256-GCM 加密入库，IV 随密文保存，密钥不落同一个库。\n3. **密钥分层**：主密钥放 KMS，数据密钥加密后存库，按租户轮换，90 天一轮。\n4. **查询支撑**：需精确匹配的字段存 HMAC 盲索引列，入参做同样 HMAC 后匹配。\n5. **展示与日志**：默认脱敏展示，统一脱敏插件，禁止打印原始报文。\n\n### 图示\n\n```mermaid\nflowchart LR\n    CL[\"客户端\"] -->|\"TLS 1.2 以上\"| GW[\"网关<br/>日志脱敏\"]\n    GW --> SVC[\"业务服务<br/>信封加密\"]\n    SVC --> DB[\"数据库<br/>AES-256-GCM 密文\"]\n    SVC --> IDX[\"盲索引列<br/>HMAC 值\"]\n    KMS[\"KMS 密钥服务<br/>KEK 主密钥\"] --> SVC\n    DB --> DEK[\"DEK 加密后存库<br/>90 天轮换\"]\n    DEK --> KMS\n    SVC --> MASK[\"展示脱敏<br/>138****1234\"]\n```\n\n### 关键选型与取舍\n\n- **字段级加密而不是整库加密**：只保护敏感字段、业务无感，代价是索引与查询受限；整库加密满足硬合规但损耗大。\n- **AES-GCM 而不是 ECB 或 CBC**：自带完整性校验，代价是相同明文密文不同，不能直接等值匹配。\n- **HMAC 盲索引而不是明文字段索引**：可精确查且不可逆推，代价是不支持范围与模糊查询，模糊需求另做方案。\n- **KMS 托管而不是写死密钥**：可轮换可审计，代价是多一次网络依赖，需本地缓存兜底。\n\n### 风险与兜底\n\n- 密钥泄露：KMS 权限最小化，解密全量审计，异常解密量突增即告警。\n- 性能下降：只加密高敏字段，解密结果本地缓存，压测确认 P99 增幅低于 10%。\n- 日志泄露：统一脱敏插件加敏感扫描，异常堆栈禁止带请求体。\n- 密文变长与索引失效：字段预留长度，盲索引单独建表，变更前评估。\n\n### 面试加分点\n\n- 加密方案先回答查询需求：要精确查就加盲索引，要模糊搜就得牺牲安全性。\n- 密钥和数据放同一个库等于没加密，密钥管理比算法更值得花时间。","sysd-036":"**一句话结论**：加密与模糊搜索天生冲突，务实做法是分级处理：精确匹配用盲索引，子串用分词令牌索引，只解密命中结果，绝不整表解密。\n\n### 约束与目标\n\n- 姓名、地址、备注等字段需要模糊查询，日查询量万级。\n- 原文已加密入库，合规不允许落明文副本供搜索。\n- 目标 P99 低于 200 毫秒，不能全表解密扫描。\n- 可接受索引额外占用 2 到 3 倍存储。\n\n### 拆解思路\n\n1. **先分查询类型**：精确匹配用 HMAC 盲索引，子串用分词令牌，任意模糊才考虑可搜索加密。\n2. **分词令牌化**：姓名做 2-gram 切分，每个 token 用带盐 HMAC 生成索引项，写入独立索引表。\n3. **查询链路**：查询词同样分词与 HMAC，按 token 交集拿主键，再回表解密少量记录。\n4. **写入一致性**：索引与主表同事务或走本地消息表同步，定时比对修正漏建索引。\n5. **极端兜底**：复杂检索走受控离线索引，带审批与审计，不开放线上任意查询。\n\n### 图示\n\n```mermaid\nflowchart LR\n    Q[\"查询词 例如 张\"] --> SPLIT[\"按 2-gram 分词\"]\n    SPLIT --> HM[\"每个 token 计算 HMAC\"]\n    HM --> IDXT[\"令牌索引表<br/>token 到主键\"]\n    IDXT -->|\"交集\"| PK[\"命中主键集合\"]\n    PK -->|\"少量回表\"| DEC[\"解密明文\"]\n    DEC --> RES[\"返回结果并脱敏\"]\n    MAIN[\"主表<br/>原文密文\"] --> DEC\n    SVC[\"写入服务\"] -->|\"同事务或 Outbox\"| IDXT\n    SVC --> MAIN\n```\n\n### 关键选型与取舍\n\n- **分词盲索引而不是可搜索加密**：简单、稳定、可审计，代价是索引泄露会暴露 token 频率；极高安全等级才上后者。\n- **独立索引表而不是给密文列建索引**：密文无规律无法直接建索引，代价是多一份存储与一致性维护。\n- **2-gram 而不是整字段哈希**：支持子串匹配，代价是索引膨胀与短词误召回。\n- **只解密命中记录而不是解密全表**：成本低，代价是索引必须准，漏召回要可观测。\n\n### 风险与兜底\n\n- 索引与主表不一致：同事务或消息补偿，定时比对修复。\n- token 频率分析攻击：HMAC 密钥按租户隔离并定期轮换，索引表仅内网可访问。\n- 短词召回爆炸：最小查询长度 2 字，结果集设上限，超限提示细化条件。\n- 索引膨胀：只对必要字段建索引，写入异步化并监控延迟。\n\n### 面试加分点\n\n- 先问业务到底要前缀、子串还是全文，能把方案成本降一个数量级。\n- 搜索索引本身也是敏感数据，权限与审计要和密文一起设计。","sysd-037":"**一句话结论**：限流只是控水位，防刷要靠多维身份计数、行为评分、挑战式验证与黑名单闭环四层叠加，单靠 IP 限流会被代理池绕过。\n\n### 约束与目标\n\n- 开放接口 QPS 峰值万级，攻击方可使用代理池与设备农场。\n- 需要区分业务高峰与恶意刷量，误杀成本高。\n- 目标拦截率 95% 以上，正常用户误杀低于 0.5%。\n\n### 拆解思路\n\n1. **多维限流**：按 appId、uid、设备指纹、手机号组合计数，IP 只作辅助权重，NAT 与代理池会让 IP 失真。\n2. **行为评分**：统计请求间隔规律性、参数重复度、UA 与指纹一致性，由规则引擎打分。\n3. **分层处置**：低分放行，中分要求滑块或短信挑战，高分直接拒绝并临时拉黑。\n4. **抬高成本**：WAF 挡常见攻击，关键接口加签加时间戳，静态资源走 CDN。\n5. **黑名单闭环**：拦截结果同步到边缘与应用两层，按小时衰减，避免长期误封。\n\n### 图示\n\n```mermaid\nflowchart LR\n    REQ[\"请求\"] --> WAF[\"WAF 与 CDN<br/>挡常见攻击\"]\n    WAF --> ID[\"多维计数<br/>appId uid 指纹 IP\"]\n    ID --> RS[\"风险评分<br/>间隔规律 参数重复 指纹一致\"]\n    RS -->|\"低分\"| PASS[\"放行\"]\n    RS -->|\"中分\"| CH[\"滑块或短信挑战\"]\n    RS -->|\"高分\"| DENY[\"拒绝并临时拉黑\"]\n    DENY --> BL[\"黑名单同步<br/>边缘与应用双层\"]\n    CH --> PASS\n    ID -->|\"超限\"| FAIL[\"快速失败\"]\n```\n\n### 关键选型与取舍\n\n- **多维计数而不是单 IP 限流**：能抗代理池，代价是存储与计算成本高，需 Redis 分片加本地预聚合。\n- **挑战式验证而不是直接封禁**：误杀友好，代价是攻击者可人工过验证，需配合指纹复用检测。\n- **规则引擎而不是纯模型**：可解释、好调参，代价是对新手法反应慢，有样本后再叠模型。\n- **边缘拦截而不是只在应用层**：省资源，代价是规则下发有延迟，应用层要二次校验兜底。\n\n### 风险与兜底\n\n- 换 IP 绕过：以设备指纹与账号为稳定维度，IP 只降权不做唯一依据。\n- 计数存储被打爆：本地滑动窗口预聚合，热点 key 分桶，超阈值快速失败。\n- 误杀正常用户：挑战优先于封禁，封禁可申诉，规则灰度上线并保留白名单。\n- 规则被摸清：阈值动态调整并加随机化，定期回放攻击样本评估拦截率。\n\n### 面试加分点\n\n- 性价比排序是加签与挑战抬高成本大于多维限流大于黑名单，先做门槛再谈规则。\n- 要同时报拦截率与误杀率，只讲限流阈值说明没做过真实对抗。","sysd-038":"**一句话结论**：滑动验证码的安全不靠图难识别，靠服务端不可预测的缺口、前端采集的轨迹特征和一次性票据，三者缺一不可。\n\n### 约束与目标\n\n- 登录注册接口 QPS 千级，需抗脚本与打码平台。\n- 一次通过率要求 90% 以上，不能为安全把用户挡住。\n- 目标机器通过率低于 1%，人工打码成本高于收益。\n\n### 拆解思路\n\n1. **服务端出题**：缺口位置在服务端随机生成并直接合成到图片，前端只拿到图和 challengeId，不下发坐标。\n2. **轨迹采集**：记录拖动过程的坐标、时间与加速度，提交时连同 challengeId 一起上送。\n3. **服务端判定**：校验 challengeId 一次性，校验轨迹是否有加速减速与抖动、总耗时是否在 300 到 2000 毫秒，校验缺口偏移小于 5 像素。\n4. **风险分级**：通过则发一次性票据；可疑转短信或二次验证；失败拒绝并记录设备指纹。\n5. **持续对抗**：图片加噪、随机干扰线、旋转扭曲，定期回放失败样本调整阈值。\n\n### 图示\n\n```mermaid\nflowchart LR\n    PC[\"前端\"] -->|\"1 申请挑战\"| SVC[\"验证服务<br/>服务端拼图 不下发缺口\"]\n    SVC -->|\"2 图片与 challengeId\"| PC\n    PC -->|\"3 拖拽提交轨迹点\"| SVC\n    SVC --> T1[\"校验 challengeId 一次性\"]\n    T1 --> T2[\"校验轨迹<br/>加速 减速 抖动 耗时\"]\n    T2 --> T3[\"校验缺口偏移小于 5 像素\"]\n    T3 -->|\"通过\"| TK[\"一次性票据<br/>绑定设备 5 分钟\"]\n    T3 -->|\"可疑\"| SMS[\"转短信二次验证\"]\n    T3 -->|\"失败\"| REJ[\"拒绝并记录指纹\"]\n    TK --> BIZ[\"业务接口\"]\n```\n\n### 关键选型与取舍\n\n- **服务端生成缺口而不是前端固定坐标**：防抓包直接读答案，代价是每请求生成图片，需预生成池与缓存。\n- **轨迹特征而不是深度学习模型**：可解释、上线快、成本低，代价是对高级模拟轨迹识别弱，需人工抽检补充。\n- **一次性票据而不是验证即放行**：票据绑定业务场景、设备与 5 分钟有效期，代价是多一次校验。\n\n### 风险与兜底\n\n- 打码平台人工通过：提高单次成本并限制同设备验证频次，通过后仍走业务风控。\n- 轨迹被脚本模拟：检测匀速直线与固定采样间隔，增加随机目标位置要求。\n- 票据复用：challengeId 一次性，token 绑定 IP 与设备指纹，超时即失效。\n- 图片生成成瓶颈：图片池预生成，合成逻辑轻量化，压测 P99 低于 100 毫秒。\n\n### 面试加分点\n\n- 验证码本质是抬高单次攻击成本，要算清打码单价与业务收益的账。\n- 验证通过不等于安全，它只是风控的一层输入，后面仍要接设备指纹与行为评分。","sysd-039":"**一句话结论**：防轰炸要三层：发送前先过滑块验证抬高成本，发送时按手机号、IP、设备、场景多维配额，发送后做通道配额与费用告警兜底。\n\n### 约束与目标\n\n- 短信单价几分钱，被刷十万条就是数千元直接损失。\n- 正常用户日均请求 1 到 3 次，活动峰值集中。\n- 目标单手机号 1 分钟 1 条、1 小时 5 条、1 天 10 条。\n- 不能明显降低正常登录的转化率。\n\n### 拆解思路\n\n1. **前置验证**：未通过滑块或图形验证就不发短信，这是最有效的一道闸。\n2. **多维配额**：手机号、IP、设备指纹、业务场景分别计数，任一超限即拒绝。\n3. **原子计数**：Redis 用 Lua 脚本原子递增，并设 60 秒、1 小时、1 天三档 TTL，防止并发绕过。\n4. **分层处置**：轻度超限返回倒计时，重度拉黑 24 小时并入风控名单，号段异常直接拒绝。\n5. **成本兜底**：通道设日配额，发送量突增即告警并切换语音或邮箱。\n\n### 图示\n\n```mermaid\nflowchart LR\n    U[\"发送验证码请求\"] --> CAP[\"前置滑块验证\"]\n    CAP -->|\"未通过 不发短信\"| REJ[\"直接拒绝\"]\n    CAP -->|\"通过\"| Q[\"多维配额校验\"]\n    Q --> Q1[\"手机号 1 分钟 1 条\"]\n    Q --> Q2[\"IP 与设备指纹 日上限\"]\n    Q --> Q3[\"号段与归属地异常\"]\n    Q -->|\"全部通过\"| SMS[\"短信通道\"]\n    SMS --> AUD[\"发送审计与费用告警\"]\n    Q -->|\"超限\"| LMT[\"稍后再试或拉黑 24 小时\"]\n    SMS -->|\"通道配额耗尽\"| ALT[\"切换语音或邮箱\"]\n```\n\n### 关键选型与取舍\n\n- **前置验证码而不是纯频率限制**：抬高单次成本，代价是牺牲一点转化，可按场景开关。\n- **Redis 原子计数而不是应用内存**：多实例共享可持久，代价是 Redis 故障需降级本地计数并收紧阈值。\n- **多维配额而不是只看手机号**：防换号刷，代价是可能误伤企业 NAT 出口，IP 阈值要放宽。\n- **明确拒绝并提示而不是静默丢弃**：用户可感知，避免重复点击造成二次请求。\n\n### 风险与兜底\n\n- 通道被盗刷产生费用：实时费用告警，发送量 10 分钟突增 3 倍即暂停并人工确认。\n- 攻击者用大量真实号码：号段频次分析、内容模板重复度检测、设备指纹聚类，命中即转挑战。\n- 并发绕过计数：Lua 原子脚本，先计数后发送，发送失败回补计数。\n- 验证码被爆破：6 位、5 分钟有效、错 5 次作废，校验同样按手机号限次。\n\n### 面试加分点\n\n- 用单条成本乘攻击量算出损失上限，再决定验证强度，比罗列手段更有说服力。\n- 发送和校验都要限次，只限发送不限校验等于留了爆破窗口。","sysd-040":"**一句话结论**：死信队列是坏消息的隔离区，价值不在存起来，而在不阻塞主链路、可查原因、可控重放三件事同时成立。\n\n### 约束与目标\n\n- 日均消息亿级，消费失败率约千分之一。\n- 失败分三类：可重试的业务异常、不可重试的脏数据、消费超时。\n- 要求消息不丢、可人工重放、能定位到原始报文。\n- 目标死信一分钟内可查，重放成功率可观测。\n\n### 拆解思路\n\n1. **定义来源**：超过最大重试次数、消费端显式拒绝、消息 TTL 过期、队列满溢出，四类统一进死信。\n2. **隔离存储**：死信落到独立 topic 与死信库，保留原始报文、失败原因、消费次数与 traceId。\n3. **分类处置**：可重试的进延迟队列指数退避重投，脏数据转工单，长期失败归档。\n4. **监控告警**：死信速率、积压量、Top 失败原因做成看板，超阈值告警到值班。\n5. **重放工具**：按条件筛选取批重投，带业务幂等键，先在测试环境验证再放量。\n\n### 图示\n\n```mermaid\nflowchart LR\n    P[\"生产者\"] --> T[\"业务 topic\"]\n    T --> C[\"消费者\"]\n    C -->|\"成功\"| ACK[\"确认消费\"]\n    C -->|\"超重试 或 reject 或 TTL\"| DLQ[\"死信 topic\"]\n    DLQ --> DB[\"死信库<br/>原始报文 失败原因 次数\"]\n    DB --> TR[\"分类处理\"]\n    TR -->|\"可重试\"| DLY[\"延迟队列<br/>指数退避\"]\n    DLY --> T\n    TR -->|\"脏数据\"| MAN[\"人工工单\"]\n    TR -->|\"长期失败\"| ARC[\"归档 7 到 30 天\"]\n    DB --> MON[\"监控告警<br/>速率 积压 Top 原因\"]\n    DB --> RP[\"重放工具<br/>限速 幂等键\"]\n    RP --> T\n```\n\n### 关键选型与取舍\n\n- **独立死信 topic 而不是原队列堆积**：不拖慢主队列，代价是多一套消费与存储；量极小时同队列加重试计数更简单。\n- **有限重试而不是无限重试**：保护下游，代价是可能误判瞬时故障，所以用指数退避加 5 到 10 次上限。\n- **落库可查而不是只留在 MQ**：便于检索与审计，代价是存储成本，按 7 到 30 天 TTL 清理。\n- **人工重放而不是全自动**：避免脏数据反复打挂下游，稳定后再做自动重放加熔断。\n\n### 风险与兜底\n\n- 死信堆积打满磁盘：积压告警并自动归档到对象存储。\n- 重放造成重复消费：消息带业务唯一键，消费端幂等表去重，重放走独立限速通道。\n- 写入失败：回落原队列并告警，或双写本地文件。\n- 原因不可定位：保留原始 payload、traceId 与堆栈摘要，脱敏后入库。\n\n### 面试加分点\n\n- 死信队列是可观测设施，设计时先回答出事怎么查、怎么重放。\n- 重放要当一次发布对待，限速、灰度、幂等、可随时停止，否则二次事故更严重。","sysd-041":"**一句话结论**：扫码登录是用手机端已登录态给 PC 端授权，核心是一个一次性短时效 scene 码加三态状态机，PC 端只负责感知状态变化。\n\n### 约束与目标\n\n- PC 端未登录、手机端已登录，扫码到确认通常 10 到 60 秒。\n- 要求 PC 端 2 秒内感知状态变化，授权成功率 99% 以上。\n- 码必须扫一次即失效，防截图与转发盗用。\n- 接入用开放平台，不自建 App 扫码体系。\n\n### 拆解思路\n\n1. **申请二维码**：PC 端调开放平台生成带 scene 的临时码，状态落 Redis 为待扫码，TTL 2 到 5 分钟。\n2. **手机扫码**：手机端解析 scene 并与当前登录 uid 绑定，状态改为已扫码待确认，PC 端展示登录端信息供核对。\n3. **手机确认**：用户点确认，服务端校验 scene 未被使用，状态置为已确认并生成一次性 code。\n4. **PC 换票**：PC 拿 code 调服务端换取 token 与 openid，建立本站会话，scene 立即删除。\n5. **状态感知**：轮询间隔 1 到 2 秒并带指数退避，体验要求高时改成 WebSocket 或 SSE 推送。\n\n### 图示\n\n```mermaid\nsequenceDiagram\n    participant PC as PC 端\n    participant S as 登录服务\n    participant R as Redis 状态\n    participant M as 手机微信\n    PC->>S: 申请带 scene 的二维码\n    S->>R: 写入待扫码状态并设 TTL\n    S-->>PC: 返回二维码并开始轮询\n    M->>S: 扫码上报 scene 与 uid\n    S->>R: 状态改为已扫码待确认\n    PC->>S: 轮询读到已扫码\n    S-->>PC: 返回待确认与登录端信息\n    M->>S: 手机端点击确认\n    S->>R: 校验 scene 未使用 置为已确认\n    S-->>PC: 轮询返回一次性 code\n    PC->>S: 用 code 换 token\n    S->>R: 删除 scene\n    S-->>PC: 建立本站会话\n```\n\n### 关键选型与取舍\n\n- **轮询而不是长连接**：实现简单、兼容性好，代价是请求量大，需退避与按 scene 限流；高体验场景再上 WebSocket。\n- **一次性 scene 而不是长期 token**：防截图重放，代价是超时要重新生成二维码。\n- **服务端换票而不是前端直接拿 openid**：appsecret 只留服务端，代价是多一次服务端调用。\n- **开放平台扫码而不是自建**：接入快、覆盖广，代价是受平台规则与费率约束。\n\n### 风险与兜底\n\n- 二维码被转发导致他人登录：scene 绑定生成端 IP 段与设备信息，确认页展示登录设备，异常可拒绝。\n- 状态丢失导致 PC 一直转圈：Redis 状态带 TTL，超时明确提示刷新。\n- 轮询打爆服务：按 scene 维度限流，前端退避，接口只返回状态不返回敏感数据。\n- code 被截获重放：code 一次性、60 秒有效、绑定 appid 与 scene，使用即失效并留审计。\n\n### 面试加分点\n\n- 体验全在三态机：待扫码、已扫码待确认、已确认，状态推送延迟直接决定用户感受。\n- 要防的不是码被看到，而是码被转发后别人替你确认，所以确认页必须展示登录端信息。"},"meta":{"id":"system-design","name":"后端系统设计面试题","generatedAt":"2026-11-07T13:41:23.769Z"}};
